import SwiftUI

enum AppBuilderStudyBank {
    static let sections: [StudySection] = [
        // Section 1: Salesforce Fundamentals (100 topics)
        StudySection(
            id: "ab-s1",
            title: "Salesforce Fundamentals",
            color: Color(red: 0.20, green: 0.45, blue: 0.70),
            lightColor: Color(red: 0.90, green: 0.95, blue: 1.00),
            icon: "cloud.fill",
            objectives: [
                StudyObjective(
                    id: "ab-s1-obj1",
                    title: "Given a scenario, identify the boundaries of declarative customization and the use cases for programmatic customization.",
                    topics: [
                        StudyTopic(id: "ab-s1-t1", number: 1, question: "A business requires real-time complex calculations on record save that involve iterating over multiple child records and updating a set of fields conditionally. Which tool should be used?", answer: "An Apex trigger (or Apex class invoked by a trigger) is required. Flow Builder cannot iterate over large sets of child records with conditional field updates in a single performant transaction. Apex handles bulkification natively, respects governor limits, and executes synchronously on record save."),
                        StudyTopic(id: "ab-s1-t2", number: 2, question: "Which categories of logic can be fully implemented with declarative tools (Flow Builder, formula fields, validation rules) without writing any code?", answer: "Declarative tools cover: field calculations (formula fields), data validation (validation rules), single/multi-record updates (record-triggered Flows), cross-object field updates (Flow Get/Update Records), approval routing, scheduled automation, screen-guided processes (Screen Flows), and simple callouts via Flow HTTP actions. Basically, anything that does not require looping over thousands of records, complex data structures, or custom UI rendering."),
                        StudyTopic(id: "ab-s1-t3", number: 3, question: "What types of requirements typically exceed Flow Builder's declarative capabilities and require Apex?", answer: "Requirements that exceed Flow: processing hundreds of thousands of records in batch jobs, complex recursive algorithms, custom REST/SOAP integrations with multi-step authentication, generating binary files (PDF, CSV), calling unsupported HTTP methods, implementing custom Visualforce controllers, and handling complex exception management with rollback logic."),
                        StudyTopic(id: "ab-s1-t4", number: 4, question: "When is an Apex batch class required rather than a scheduled Flow to process large volumes of records?", answer: "Apex Batch is needed when the record volume exceeds Flow's per-transaction limits (50,000 record collection cap in Flow) or when you need chunked processing with configurable batch sizes, sophisticated error handling per chunk, or complex multi-object logic that would hit Flow governor limits. Scheduled Flows work well for smaller, simpler sets but are not designed for millions of records."),
                        StudyTopic(id: "ab-s1-t5", number: 5, question: "A business requirement calls for generating a formatted PDF document from Salesforce record data. Does Salesforce provide a native declarative solution for this, or is code/AppExchange required?", answer: "Salesforce has no native declarative PDF generation tool. The options are: (1) a Visualforce page rendered as PDF using Apex, or (2) an AppExchange managed package (e.g., Conga Composer, Nintex DocGen). For a no-code approach, an AppExchange solution is the recommended path."),
                        StudyTopic(id: "ab-s1-t6", number: 6, question: "A company needs to send an HTTP callout to an external REST API when a record is saved. Can this be done declaratively, and if so, how?", answer: "Yes, this can be done declaratively using a Flow with an HTTP Callout action (available in Winter '23+). You configure a Named Credential for authentication and use the 'HTTP Callout' core action in an after-save record-triggered Flow. For complex scenarios (authentication flows, multi-step API chains), Apex remains the more robust option."),
                        StudyTopic(id: "ab-s1-t7", number: 7, question: "When is a Visualforce page or Lightning Web Component required rather than a standard Lightning page layout for a user interface requirement?", answer: "Custom UI code is needed when: the UI requires custom rendering logic not achievable with standard components, you need interactive data tables with inline editing, the page must embed third-party JavaScript libraries, you need a wizard-style multi-step UI beyond what Screen Flow supports, or the user experience requires real-time data manipulation without page refreshes."),
                        StudyTopic(id: "ab-s1-t8", number: 8, question: "What is the declarative boundary for complex branching logic that must evaluate dozens of conditions and update many unrelated records in a single transaction?", answer: "Flow Builder's Decision element can handle dozens of conditions, and Update Records can update unrelated objects. However, if those unrelated updates span more than a handful of object types, or if the branching is deeply nested with hundreds of paths, maintainability suffers and Apex becomes the better long-term choice. The practical boundary is complexity of maintenance, not a hard platform limit."),
                        StudyTopic(id: "ab-s1-t9", number: 9, question: "Which operations cannot be performed by any declarative automation tool and always require Apex code?", answer: "Operations always requiring Apex: parsing/generating binary data, implementing custom REST API endpoints (Apex REST), bulk processing with Batchable/Queueable patterns, complex SOSL searches with programmatic result handling, implementing custom iterable patterns, and triggering before-insert logic that must manipulate the record before it receives an ID."),
                        StudyTopic(id: "ab-s1-t10", number: 10, question: "When is a custom Apex trigger required rather than a record-triggered Flow to handle record logic?", answer: "An Apex trigger is required when: you need before-insert logic that sets fields before the record gets an ID (Flow before-save can do some of this but is more limited), you need to process extremely large batches with custom governor limit management, you require complex recursive guard patterns across multiple objects, or you need to call future/queueable methods with specific chaining logic."),
                        StudyTopic(id: "ab-s1-t11", number: 11, question: "Select two requirements that would exceed Flow Builder's declarative capabilities and require Apex.", answer: "Two good examples: (1) Processing a nightly batch of 500,000 records with conditional updates — exceeds Flow's per-transaction limit, requires Apex Batch. (2) Generating a formatted PDF from record data — no native declarative solution, requires Visualforce/Apex or AppExchange. Other valid examples include complex multi-step HTTP OAuth flows and custom Visualforce UI logic."),
                        StudyTopic(id: "ab-s1-t12", number: 12, question: "What are the key functional differences between Lightning Experience and Salesforce Classic that a platform app builder must understand?", answer: "Lightning Experience offers: Lightning App Builder for drag-and-drop pages, Dynamic Forms, component-based architecture, improved report/dashboard UI, Kanban views, Path component, Activity Timeline, and mobile-responsive design. Classic lacks these modern features and uses S-controls/JavaScript buttons (now deprecated). Lightning components (LWC/Aura) only work in Lightning Experience or Experience Cloud, not Classic."),
                        StudyTopic(id: "ab-s1-t13", number: 13, question: "What is My Domain in Salesforce and why is it required before Lightning components can be embedded in App Builder pages or used for single sign-on?", answer: "My Domain is an org-specific subdomain (e.g., mycompany.my.salesforce.com). It is required because Lightning components use the domain for secure cross-frame communication (clickjack protection). Without My Domain, the platform cannot reliably scope cookies and authenticate component requests. It is also a prerequisite for SAML-based SSO and OAuth connected apps."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s1-obj2",
                    title: "Identify common scenarios for extending an org using the AppExchange.",
                    topics: [
                        StudyTopic(id: "ab-s2-t1", number: 1, question: "What types of solutions are available on the AppExchange (apps, components, flows, data services)?", answer: "AppExchange hosts: full apps (CRM add-ons, CPQ, ERP connectors), Lightning components (individual LWC or Aura components for App Builder), Flow templates and solutions, Bolt Solutions (Experience Cloud templates), and data services (data enrichment, cleansing). Both free and paid offerings exist."),
                        StudyTopic(id: "ab-s2-t2", number: 2, question: "What is the difference between a managed package and an unmanaged package on the AppExchange?", answer: "Managed package: code is protected (Apex is compiled, not readable), the ISV can push upgrades, and the namespace prefix prevents conflicts. Unmanaged package: all metadata is fully editable after install, no upgrade path, used for sharing open templates. AppExchange publicly listed solutions are always managed packages."),
                        StudyTopic(id: "ab-s2-t3", number: 3, question: "A company needs advanced document generation capabilities that Salesforce does not provide natively. What is the recommended approach?", answer: "Install a managed AppExchange package such as Conga Composer, Nintex DocGen, or Docusign for document generation. These solutions integrate natively with Salesforce data, support PDF/Word output, and can be triggered from buttons or automation. This avoids custom Apex development and leverages pre-built, security-reviewed solutions."),
                        StudyTopic(id: "ab-s2-t4", number: 4, question: "What security process must every AppExchange managed package pass before it can be listed publicly?", answer: "Every AppExchange managed package must pass a Salesforce Security Review. This includes automated scanning plus manual review of code and metadata for security vulnerabilities, compliance with Salesforce security standards, and protection of customer data. Only after passing this review can a package be publicly listed."),
                        StudyTopic(id: "ab-s2-t5", number: 5, question: "Can an AppExchange solution be installed in a sandbox before deploying to production?", answer: "Yes. Best practice is to install and test any AppExchange package in a sandbox first. During installation you select the target environment (sandbox or production). This allows UAT, configuration testing, and conflict assessment before rolling out to production users."),
                        StudyTopic(id: "ab-s2-t6", number: 6, question: "What are common business scenarios where AppExchange packages provide value over native Salesforce features (e.g., CPQ, ERP integration, advanced analytics)?", answer: "Common scenarios: CPQ (Configure-Price-Quote) for complex pricing logic, ERP integration connectors (SAP, NetSuite), advanced analytics (Tableau CRM pre-built apps), document generation, e-signature, telephony/CTI integrations, project management, territory management extensions, and advanced marketing automation beyond Marketing Cloud basics."),
                        StudyTopic(id: "ab-s2-t7", number: 7, question: "When should a company choose to build a custom solution rather than installing an AppExchange package?", answer: "Build custom when: no suitable package exists, the requirement is highly proprietary and a competitive differentiator, data privacy restrictions prevent third-party access, the package's cost/complexity outweighs building it internally, or the business process is too unique to map to an off-the-shelf product. AppExchange is preferred when a well-reviewed solution already exists."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s1-obj3",
                    title: "Apply features and capabilities available to restrict and extend object, record, and field access.",
                    topics: [
                        StudyTopic(id: "ab-s3-t1", number: 1, question: "What is the difference between a profile and a permission set in terms of access control?", answer: "A profile is mandatory — every user has exactly one. It sets baseline object permissions, field access, login hours, IP restrictions, and app visibility. A permission set is additive and optional — it grants additional permissions on top of the profile without removing anything. Permission sets are the recommended way to grant elevated access without changing profiles."),
                        StudyTopic(id: "ab-s3-t2", number: 2, question: "What is object-level security and how is it configured?", answer: "Object-level security controls whether a user can Read, Create, Edit, Delete, View All, or Modify All records on an object. It is configured on profiles and permission sets. If a user lacks Read on an object, they cannot see that object's tab, records, or related lists anywhere in the org."),
                        StudyTopic(id: "ab-s3-t3", number: 3, question: "What is record-level security and how does it layer on top of object-level security?", answer: "Record-level security determines which specific records a user can see and edit, given they already have object access. It is configured through: OWD (org-wide defaults), role hierarchy, sharing rules, manual sharing, and teams. A user must first pass object-level security, then record-level security restricts which records are visible."),
                        StudyTopic(id: "ab-s3-t4", number: 4, question: "What does the 'View All' object permission do, and how does it differ from the role hierarchy granting access to records?", answer: "'View All' on an object grants read access to every record regardless of OWD, sharing rules, or ownership. The role hierarchy grants access only to records owned by subordinates in the hierarchy. 'View All' is a flat permission ignoring the hierarchy entirely, and it overrides all sharing restrictions."),
                        StudyTopic(id: "ab-s3-t5", number: 5, question: "What does the 'Modify All' object permission do?", answer: "'Modify All' grants full read, edit, delete, transfer, and approve access to every record on that object, regardless of OWD or sharing. It also implicitly includes 'View All'. It is the most powerful record-level permission and is typically reserved for system admins or data stewards."),
                        StudyTopic(id: "ab-s3-t6", number: 6, question: "What is a permission set group and when would you use one?", answer: "A permission set group bundles multiple permission sets into a single assignable unit. Instead of assigning five separate permission sets to a user, you create one group containing all five and assign the group. Useful when a persona (e.g., 'Field Sales Rep') consistently needs a defined set of permissions across multiple domains."),
                        StudyTopic(id: "ab-s3-t7", number: 7, question: "How does a muting permission set work within a permission set group?", answer: "A muting permission set removes specific permissions from a permission set group for a subset of users. For example, if a group grants 'Delete Accounts' but certain users in that group should not have delete access, you create a muting permission set that revokes 'Delete Accounts' and apply it to those users. It only suppresses — it cannot grant new permissions."),
                        StudyTopic(id: "ab-s3-t8", number: 8, question: "What is field-level security (FLS) and how does it differ from object-level security?", answer: "FLS controls access to specific fields on an object — whether a user can see (Read) or edit (Edit) individual fields. Object-level security controls whether the user can access the object at all. FLS is more granular: a user may have Read on Accounts but have the 'Annual Revenue' field hidden via FLS."),
                        StudyTopic(id: "ab-s3-t9", number: 9, question: "What is the difference between 'Read' and 'Edit' object permissions when assigned on a profile?", answer: "'Read' allows viewing records but not modifying them. 'Edit' allows modifying records the user has access to, but does not automatically grant access to all records — record-level security still applies. Edit includes Read by default. To create records, the 'Create' permission must also be granted."),
                        StudyTopic(id: "ab-s3-t10", number: 10, question: "A user needs temporary elevated access to an object for a specific project. Which approach is preferred: editing their profile or assigning a permission set?", answer: "Assign a permission set. Editing a profile affects all users on that profile — a broad, high-risk change. A permission set is assigned specifically to the individual user, can be removed when the project ends, and follows the least-privilege principle. Profiles should be changed only when the entire group needs the new access."),
                        StudyTopic(id: "ab-s3-t11", number: 11, question: "If a user's profile denies read access to a field but a permission set grants read access to that field, what is the effective access?", answer: "The user gets Read access to the field. Salesforce uses a 'most permissive wins' model for combining profiles and permission sets. Permission sets can only add permissions, not remove them. So if any assigned permission set grants field access, the user has that access regardless of what the profile says."),
                        StudyTopic(id: "ab-s3-t12", number: 12, question: "Select two statements that are true about the relationship between profiles and permission sets in Salesforce access control.", answer: "True statements: (1) Every user must have exactly one profile, but can have zero or more permission sets. (2) Permission sets can only grant additional access — they cannot revoke permissions granted by the profile (except via muting permission sets in a permission set group). These two facts are frequently tested on the exam."),
                        StudyTopic(id: "ab-s3-t13", number: 13, question: "What are login hours on a Salesforce profile and how do they restrict when a user can log in?", answer: "Login Hours on a profile define a time window (by day of week) during which users on that profile can log in. If a user is already logged in when their login hours expire, they are logged out at the next page load. This is commonly used for external user profiles or shift-based internal users."),
                        StudyTopic(id: "ab-s3-t14", number: 14, question: "What are the three tab visibility settings available on a profile or permission set (Default On, Default Off, Tab Hidden) and how does each affect what the user sees?", answer: "Default On: the tab appears in the navigation bar unless the user removes it. Default Off: the tab is available but hidden by default; users can add it themselves. Tab Hidden: the tab is completely invisible to the user and cannot be added. Object access is separate from tab visibility — hiding a tab does not remove record access."),
                        StudyTopic(id: "ab-s3-t15", number: 15, question: "What are login IP ranges on a Salesforce profile and how do they restrict from where a user can log in?", answer: "Login IP Ranges on a profile restrict logins to specified IP address ranges. If a user attempts to log in from an IP outside the defined range, they are blocked (or challenged with email verification, depending on org settings). This adds a location-based security layer, useful for internal users who should only access Salesforce from corporate networks."),
                        StudyTopic(id: "ab-s3-t16", number: 16, question: "A user with 'Read' object permission on Accounts should see only accounts they own, but their manager must also see them. What combination of OWD and sharing mechanism satisfies this without changing profiles?", answer: "Set Account OWD to 'Private'. Enable 'Grant Access Using Hierarchies' on the Account object (enabled by default). The manager will automatically see subordinates' account records through the role hierarchy. The user's profile Read permission remains unchanged — OWD and the role hierarchy handle the visibility."),
                        StudyTopic(id: "ab-s3-t17", number: 17, question: "What is the 'View All Data' system permission and how does it differ from 'View All' on an individual object?", answer: "'View All Data' is a system-level permission that grants read access to all records across every object in the org — it is essentially 'View All' applied org-wide. 'View All' on an individual object is scoped only to that one object. 'View All Data' is typically reserved for system administrators."),
                        StudyTopic(id: "ab-s3-t18", number: 18, question: "What is a restriction rule and how does it differ from a sharing rule — does it open or restrict record visibility?", answer: "A restriction rule restricts record visibility — it narrows down which records a user can see below what OWD and sharing rules would normally allow. Sharing rules only open up access (from Private OWD). Restriction rules are the declarative way to reduce access for specific users or groups without changing the overall OWD."),
                        StudyTopic(id: "ab-s3-t19", number: 19, question: "Select two things that can be controlled by a permission set that cannot be controlled by a profile.", answer: "Permission sets can: (1) be assigned to individual users without affecting other users on the same profile, and (2) be packaged and distributed in managed packages (enabling ISVs to ship permissions with their app). Profiles cannot be assigned to multiple configurations per user, and they cannot be packaged the same way. Both tools control object/field permissions, but permission sets offer user-level granularity."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s1-obj4",
                    title: "Given a set of business requirements, determine the appropriate sharing solution.",
                    topics: [
                        StudyTopic(id: "ab-s4-t1", number: 1, question: "What are the possible Organization-Wide Default (OWD) settings for a custom object?", answer: "For custom objects, OWD options are: Private (only owner and users above in hierarchy see records), Public Read Only (everyone can read, only owner/hierarchy can edit), Public Read/Write (everyone can read and edit), and Public Read/Write/Transfer (for cases/leads, allows changing ownership). Controlled by Parent is available when the object has a master-detail to another object."),
                        StudyTopic(id: "ab-s4-t2", number: 2, question: "What is the role hierarchy in Salesforce and how does it grant record access upward?", answer: "The role hierarchy is a tree structure representing the reporting chain. When 'Grant Access Using Hierarchies' is enabled, users in roles above the record owner automatically gain at least the same access level as the owner. Access flows upward only — a manager sees subordinates' records, not vice versa."),
                        StudyTopic(id: "ab-s4-t3", number: 3, question: "What is the difference between an owner-based sharing rule and a criteria-based sharing rule?", answer: "Owner-based sharing rule: shares records owned by users in a specific role/group with another group. Criteria-based sharing rule: shares records whose field values match specified criteria (e.g., Region = 'West') with a group, regardless of who owns the record. Criteria-based is more flexible for data-attribute-driven sharing."),
                        StudyTopic(id: "ab-s4-t4", number: 4, question: "When can sharing rules NOT be used to open up access (i.e., when OWD is already Public Read/Write)?", answer: "Sharing rules can only grant access that is more permissive than the OWD. If OWD is already Public Read/Write, sharing rules have nothing to add because everyone already has maximum access. Sharing rules are only relevant when OWD is set to Private or Public Read Only."),
                        StudyTopic(id: "ab-s4-t5", number: 5, question: "What is manual sharing and when is it available to users?", answer: "Manual sharing allows a record owner (or admin) to share a specific record with a specific user or group on a one-off basis using the 'Sharing' button. It is available only when the object's OWD is Private or Public Read Only — not when OWD is Public Read/Write. Manual shares are removed when record ownership changes."),
                        StudyTopic(id: "ab-s4-t6", number: 6, question: "A company has sensitive opportunity records that should only be visible to the owner and their management chain. Which OWD setting and sharing components support this?", answer: "Set Opportunity OWD to Private. Enable 'Grant Access Using Hierarchies' (default on Opportunities). Managers in roles above the owner will automatically see those records. No sharing rules are needed unless cross-team visibility is required. This is the most restrictive, secure baseline for sensitive pipeline data."),
                        StudyTopic(id: "ab-s4-t7", number: 7, question: "What is a public group and when should you use a public group instead of a role for a sharing rule?", answer: "A public group is a manually curated collection of users, roles, or other groups used as a sharing target. Use a public group instead of a role when: the sharing audience does not map neatly to a single role (e.g., members from multiple roles), or when the set of users changes independently of the role hierarchy. Public groups are more flexible for ad-hoc groupings."),
                        StudyTopic(id: "ab-s4-t8", number: 8, question: "What is the maximum number of sharing rules allowed per object?", answer: "Salesforce allows up to 300 sharing rules per object (combined owner-based and criteria-based). This limit is rarely hit in practice, but it is important to be aware of when designing a complex sharing model with many criteria-based rules."),
                        StudyTopic(id: "ab-s4-t9", number: 9, question: "A requirement states that users in the 'Support' role should have read access to all cases owned by users in the 'Sales' role. What sharing feature satisfies this?", answer: "Create an owner-based sharing rule on the Case object: share records owned by users in the 'Sales' role with users in the 'Support' role, granting Read Only access. This is a straightforward role-to-role owner-based sharing rule, the most common use case for sharing rules."),
                        StudyTopic(id: "ab-s4-t10", number: 10, question: "What is the order of evaluation Salesforce uses to determine whether a user can access a specific record?", answer: "Salesforce evaluates access in this order: (1) Is the object accessible via the user's profile/permission set? (2) Is the record owned by the user, or are they above the owner in the role hierarchy? (3) Does a sharing rule grant access? (4) Is there a manual share? (5) Does the user have 'View All' or 'View All Data'? The most permissive applicable rule wins."),
                        StudyTopic(id: "ab-s4-t11", number: 11, question: "What are the limitations of manual sharing (e.g., it is removed when record ownership changes, not available when OWD is Public Read/Write)?", answer: "Manual sharing limitations: (1) Removed automatically when the record owner changes. (2) Not available when OWD is Public Read/Write — no need to share manually when everyone already has access. (3) Cannot be automated — it requires a human to click 'Sharing' or use Apex. (4) It does not persist across ownership transfers."),
                        StudyTopic(id: "ab-s4-t12", number: 12, question: "A company needs to grant read access to all Opportunity records owned by users in a specific territory role to a cross-functional team. Select two sharing tools that can accomplish this declaratively.", answer: "Two declarative options: (1) Owner-based sharing rule — share records owned by users in the territory role with the cross-functional public group/role. (2) Criteria-based sharing rule — if territory is stored as a field on the Opportunity, share based on that field value. Both are valid; the right choice depends on whether ownership or field value is the better trigger."),
                        StudyTopic(id: "ab-s4-t13", number: 13, question: "How does assigning a record to a queue affect who can access that record?", answer: "When a record is assigned to a queue, all members of that queue gain access to the record (at the OWD access level or above). Any queue member can then accept (take ownership of) the record. This is commonly used for case or lead routing where a pool of users should be able to pick from a shared workload."),
                        StudyTopic(id: "ab-s4-t14", number: 14, question: "What is a Salesforce queue and which standard objects support it?", answer: "A queue is a holding area for records awaiting assignment. Standard objects supporting queues: Cases, Leads, Orders, Knowledge Articles, and custom objects. Contacts, Accounts, and Opportunities do not support queues natively. Queue members can be individual users, roles, or public groups."),
                        StudyTopic(id: "ab-s4-t15", number: 15, question: "What are account teams, and what types of access (Read/Write) can account team members be granted on the account and its related records?", answer: "Account teams are a group of users who collaborate on an account. Each team member can be granted Read or Edit access to the Account itself, and separately Read or Edit access to related Contacts, Opportunities, and Cases. The account owner defines the team. This provides fine-grained related-object sharing without public groups or sharing rules."),
                        StudyTopic(id: "ab-s4-t16", number: 16, question: "What is the 'Grant Access Using Hierarchies' setting on a custom object, and what happens to record access through the role hierarchy when it is disabled?", answer: "This setting controls whether users above the record owner in the role hierarchy automatically inherit record access. When disabled on a custom object, the role hierarchy does NOT grant upward access — managers do not automatically see their subordinates' records on that object. Sharing rules and manual sharing would need to compensate. Standard objects cannot disable this setting."),
                        StudyTopic(id: "ab-s4-t17", number: 17, question: "What are opportunity teams and what access levels can team members be granted on an opportunity?", answer: "Opportunity teams let multiple users collaborate on a single opportunity. Each member can be granted Read Only or Read/Write access to the opportunity record. Unlike account teams, opportunity team access is scoped only to that specific opportunity — it does not automatically extend to related objects."),
                        StudyTopic(id: "ab-s4-t18", number: 18, question: "How does implicit sharing work for Contacts, Opportunities, and Cases that are related to an Account — what access does a user gain to child records when they have access to the parent Account?", answer: "Implicit sharing means that if a user has Read access to an Account, Salesforce automatically grants Read access to that Account's related Contacts, Opportunities, and Cases — even if the OWD on those child objects is Private. This is a built-in platform behavior designed to ensure users can navigate related records contextually."),
                        StudyTopic(id: "ab-s4-t19", number: 19, question: "A company needs 10 regional reps to each own a queue of cases. When a rep picks a case, it should leave the queue and be owned by the rep. Which sharing feature supports this assignment model?", answer: "Queues support this model. Cases are assigned to the queue (shared with all queue members). When a rep 'accepts' the case, they change the owner to themselves, removing it from the queue. Each region can have its own queue. This is the standard Salesforce case assignment model."),
                        StudyTopic(id: "ab-s4-t20", number: 20, question: "A company uses a Opportunities object with OWD set to Private. A sales manager needs real-time access to all opportunity records owned by their direct reports but not by peers in other regions. Which sharing mechanism provides this without writing any code?", answer: "The role hierarchy with 'Grant Access Using Hierarchies' enabled provides this automatically. The sales manager's role must be positioned above their direct reports' roles in the hierarchy. They will see all subordinate-owned opportunities. Peer records in other regions remain private because there is no hierarchical relationship between the peers."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s1-obj5",
                    title: "Identify the features and capabilities available when creating reports, report types, and dashboards.",
                    topics: [
                        StudyTopic(id: "ab-s5-t1", number: 1, question: "What are the four report formats available in Salesforce (Tabular, Summary, Matrix, Joined)?", answer: "Tabular: simple row list, no grouping, good for exports. Summary: groups rows by a field (e.g., by Stage), allows subtotals and charts. Matrix: groups by both rows and columns, great for pivot-style analysis. Joined: up to five report blocks of different report types side-by-side in one report, used for comparing disparate data sets."),
                        StudyTopic(id: "ab-s5-t2", number: 2, question: "What is the difference between a standard report type and a custom report type?", answer: "Standard report types are pre-built by Salesforce for common object relationships (e.g., Accounts with Contacts). Custom report types are admin-created and allow you to define which objects (up to 4 related objects) are included and whether child records must or may exist, and you can add any fields from those objects."),
                        StudyTopic(id: "ab-s5-t3", number: 3, question: "When would you create a custom report type instead of using a standard report type?", answer: "Create a custom report type when: the standard type doesn't include the fields or related objects you need, you want to report on a custom object relationship, you need to specify include/exclude behavior for child records (e.g., Accounts without Contacts), or you need to expose formula fields or related object fields not in any standard type."),
                        StudyTopic(id: "ab-s5-t4", number: 4, question: "What is a joined report and when is it appropriate to use one?", answer: "A joined report displays up to 5 report blocks side-by-side, each based on a different report type but sharing a common standard object. Use it when you need to compare data from different object contexts in one view — for example, comparing Opportunities and Cases for the same Account. Each block can have its own filters and groupings."),
                        StudyTopic(id: "ab-s5-t5", number: 5, question: "What is a dashboard in Salesforce and what types of components can it contain?", answer: "A dashboard is a visual display of report data. Component types include: charts (bar, line, donut, funnel, scatter), gauges, metrics (single number KPIs), tables, and Visualforce pages. Each component is powered by a source report. Dashboards are stored in folders and can be filtered by viewers."),
                        StudyTopic(id: "ab-s5-t6", number: 6, question: "What is the maximum number of records a standard Salesforce report displays?", answer: "A standard Salesforce report displays a maximum of 2,000 rows in the report viewer. However, if you export the report, you can retrieve up to 200,000 rows (via export to CSV). The 2,000-row limit applies only to the on-screen display, not to report subscriptions or exports."),
                        StudyTopic(id: "ab-s5-t7", number: 7, question: "What is a dynamic dashboard and how does it differ from a standard dashboard?", answer: "A dynamic dashboard shows data based on the logged-in user's own record access, rather than the 'Run As' user defined on the dashboard. Each user sees their own data in real time. Standard dashboards show data as a single fixed user. Dynamic dashboards are useful for sales rep scorecards where each person should see only their own pipeline."),
                        StudyTopic(id: "ab-s5-t8", number: 8, question: "What is the maximum number of components on a single dashboard?", answer: "A single Salesforce dashboard can contain up to 20 components. This is a key exam fact. If you need more than 20 visualizations, you must create multiple dashboards or combine data more efficiently in fewer components."),
                        StudyTopic(id: "ab-s5-t9", number: 9, question: "What is the 'Run as' setting on a dashboard, and what options are available?", answer: "The 'Run as' setting determines whose security context is used to pull dashboard data. Options: (1) Run as specified user — data always reflects that user's access (good for a manager's view), (2) Run as logged-in user (dynamic dashboard) — each viewer sees their own data, (3) Run as scheduled user — used for scheduled dashboard refreshes. The 'Run as' user must have access to all source reports."),
                        StudyTopic(id: "ab-s5-t10", number: 10, question: "Can a custom report type include fields from objects that are up to four levels away in a lookup relationship chain?", answer: "Yes. A custom report type can span up to 4 related objects (e.g., Object A > Object B > Object C > Object D). Fields from all four objects can be included in the report. This is the maximum depth for a custom report type relationship chain."),
                        StudyTopic(id: "ab-s5-t11", number: 11, question: "What is a bucket field in a report and when would you use one?", answer: "A bucket field lets you categorize report records into groups (buckets) on the fly without creating a formula field. For example, bucket 'Annual Revenue' into Small (<1M), Medium (1M-10M), Large (>10M). Use it for ad-hoc segmentation in a report without modifying the data model. Buckets support Numeric, Text, and Picklist field types."),
                        StudyTopic(id: "ab-s5-t12", number: 12, question: "What is a dashboard filter and how does it allow a viewer to adjust the dashboard display without editing it?", answer: "Dashboard filters are pre-configured filter options that viewers can select from a dropdown on the dashboard. The admin defines up to 3 filters per dashboard, specifying which fields and values are available. Viewers toggle filters to slice the dashboard data (e.g., by Region or Quarter) without needing edit access to the dashboard."),
                        StudyTopic(id: "ab-s5-t13", number: 13, question: "What is a cross filter in a report, and what type of question does it answer (e.g., Accounts without Opportunities)?", answer: "A cross filter lets you filter the primary report object based on the presence or absence of related records. For example: 'Show all Accounts where NO Opportunities exist.' This answers 'with/without' questions about related objects. Cross filters can also be refined with sub-filters on the related object's fields."),
                        StudyTopic(id: "ab-s5-t14", number: 14, question: "How is report and dashboard folder visibility controlled, and which settings determine which users can view or edit a given folder?", answer: "Folder access is controlled by sharing the folder with users, roles, public groups, or the entire org. Access levels are Viewer (can run reports/view dashboards), Editor (can also create/edit within the folder), and Manager (can also share and rename the folder). Reports/dashboards are always stored in a folder — 'My Personal Reports' is visible only to the owner."),
                        StudyTopic(id: "ab-s5-t15", number: 15, question: "What is a report subscription in Salesforce and how does it differ from scheduling a dashboard refresh?", answer: "A report subscription sends the report results by email on a defined schedule (daily, weekly, monthly) to specified users. Dashboard refresh scheduling re-runs the dashboard's source reports and caches the data at a set time. Report subscriptions deliver a snapshot of the data to inboxes; dashboard scheduling ensures the on-screen dashboard is up-to-date when users log in."),
                        StudyTopic(id: "ab-s5-t16", number: 16, question: "What is conditional highlighting (formatting) in a Salesforce report and on which report formats is it available?", answer: "Conditional highlighting colors cell backgrounds based on numeric thresholds (e.g., green for >90%, yellow for 70-90%, red for <70%). It is only available on Summary and Matrix report formats — not Tabular or Joined. It applies to numeric summary fields like totals, averages, or counts."),
                        StudyTopic(id: "ab-s5-t17", number: 17, question: "What is a row limit on a Tabular report and when is it required before the report can be used as a dashboard source?", answer: "A Tabular report must have a row limit applied (max 2,000) before it can be used as a dashboard source. Without a row limit, Tabular reports cannot power dashboard components. The row limit defines how many rows the dashboard component will draw from. Summary and Matrix reports do not require this step."),
                        StudyTopic(id: "ab-s5-t18", number: 18, question: "In a custom report type that spans two objects, what is the difference between selecting 'Each A record must have at least one related B record' versus 'A records may or may not have related B records'?", answer: "'Each A must have at least one B' acts like an inner join — only A records with at least one related B appear in the report. 'A may or may not have B' acts like an outer join — all A records appear, and B fields are blank for those without related B records. The second option is needed for 'Accounts without Opportunities' style reporting."),
                        StudyTopic(id: "ab-s5-t19", number: 19, question: "What is a summary formula column in a Summary or Matrix report and how does it differ from a standard report field?", answer: "A summary formula column is a custom calculated column built using report-level aggregate functions (SUM, AVG, MAX, MIN, COUNT) on other report fields. It exists only in the report — not in the Salesforce schema. A standard report field maps directly to an object field. Summary formulas allow KPIs like 'Win Rate = Closed Won / Total Opportunities' that cannot exist as a schema-level field."),
                        StudyTopic(id: "ab-s5-t20", number: 20, question: "What are the available chart types for a dashboard component and what data shapes (Summary, Matrix) support them?", answer: "Chart types include: bar, horizontal bar, line, donut, funnel, scatter, and combo. Summary reports support bar, line, donut, funnel, and scatter charts. Matrix reports also support those types. Gauge and Metric components don't use charts but show a single aggregated value. Tabular reports with a row limit can use table components."),
                        StudyTopic(id: "ab-s5-t21", number: 21, question: "What is the maximum number of columns on a single Salesforce dashboard?", answer: "A Salesforce dashboard supports up to 3 columns. This is a fixed layout constraint. Dashboard components can be sized to span 1, 2, or all 3 columns, allowing flexible arrangements while staying within the 3-column maximum."),
                        StudyTopic(id: "ab-s5-t22", number: 22, question: "What is the maximum number of components on a single Salesforce dashboard?", answer: "A single Salesforce dashboard supports a maximum of 20 components. This limit applies regardless of column layout. If more visualizations are needed, additional dashboards must be created, or data must be consolidated into fewer components using more efficient report designs."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s1-obj6",
                    title: "Given a set of requirements, determine the appropriate global, object-specific actions and layouts to optimize the Salesforce mobile user experience.",
                    topics: [
                        StudyTopic(id: "ab-s6-t1", number: 1, question: "What is the difference between a global action and an object-specific quick action?", answer: "A global action is available from anywhere in Salesforce (the global header action bar, Chatter, mobile navigation) and is not associated with a specific object. An object-specific quick action belongs to a specific object and appears on that object's record page. Global actions are best for org-wide tasks (Log a Call, New Task); object-specific actions are best for context-driven tasks (Create related Contact from Account)."),
                        StudyTopic(id: "ab-s6-t2", number: 2, question: "What types of quick actions exist (Create, Update, Log a Call, Custom Visualforce, Flow)?", answer: "Quick action types: Create (creates a new record, optionally pre-populating related fields), Update (updates fields on the current record), Log a Call (creates a Task with Call type), Custom Visualforce (opens a VF page), Flow (launches a Screen Flow), Send Email (sends an email), and Custom Canvas (for connected apps). Each type serves a different UX goal."),
                        StudyTopic(id: "ab-s6-t3", number: 3, question: "When would you use an 'Update a Record' quick action instead of a 'Create a Record' quick action?", answer: "Use 'Update a Record' when the user needs to edit specific fields on the current record quickly — for example, a status update action showing only 3 fields instead of the full page layout. This reduces cognitive load and is ideal for mobile where screen space is limited. 'Create a Record' is for adding new records, not modifying existing ones."),
                        StudyTopic(id: "ab-s6-t4", number: 4, question: "How are quick actions surfaced in the Salesforce mobile app?", answer: "In the Salesforce mobile app, quick actions appear in the action bar at the bottom of a record (the row of icons). The order and selection of actions in the action bar is controlled by the page layout's 'Salesforce Mobile and Lightning Experience Actions' section. The first few actions in the layout become the visible quick-access icons; the rest appear in an overflow menu."),
                        StudyTopic(id: "ab-s6-t5", number: 5, question: "What is the mobile navigation menu and how can it be customized?", answer: "The mobile navigation menu is the left-side menu in the Salesforce mobile app that users access via the hamburger icon. Admins customize it in Setup under 'Salesforce Navigation' by selecting which items (objects, apps, smart search items, Visualforce pages, Lightning pages) appear and in what order. The first item becomes the mobile app's home screen."),
                        StudyTopic(id: "ab-s6-t6", number: 6, question: "What is a compact layout and when is it displayed in the mobile app?", answer: "A compact layout defines which fields appear in the highlights panel at the top of a record (the card header with the record's most important fields). In the mobile app, compact layouts also appear in record cards in list views and related lists. An admin selects 4-10 fields for the compact layout. The top 4 fields get the most prominent display."),
                        StudyTopic(id: "ab-s6-t7", number: 7, question: "A sales rep needs to quickly log a call note after a client meeting from their phone. Which action type should be configured?", answer: "Configure a 'Log a Call' quick action on the relevant object (e.g., Contact or Opportunity). This action creates a Task record pre-set to Call type, with a notes/description field. It is optimized for fast data entry and is prominently displayed in the mobile app action bar. No navigation away from the record is needed."),
                        StudyTopic(id: "ab-s6-t8", number: 8, question: "A requirement states that users need to create a new Case from anywhere in the app, not just from the Cases object. Which action type satisfies this?", answer: "Create a global action of type 'Create a Record' targeting the Case object. Add it to the global publisher layout. This makes the 'New Case' action available from the global header and the mobile action bar everywhere in the app — not just on the Cases tab. Global actions are the go-to for org-wide, context-independent record creation."),
                        StudyTopic(id: "ab-s6-t9", number: 9, question: "What is the maximum number of fields recommended in an action layout for optimal mobile usability?", answer: "Salesforce recommends no more than 8 fields on an action layout for mobile usability. Fewer fields mean less scrolling and faster data entry on small screens. Action layouts are separate from full page layouts and should be intentionally minimal, capturing only the essential fields needed to complete the action."),
                        StudyTopic(id: "ab-s6-t10", number: 10, question: "How does the action layout differ from the full page layout, and how does it affect the mobile user experience?", answer: "The action layout is a stripped-down layout specific to a quick action — it contains only the fields needed for that action (e.g., 3-5 fields to create a lead). The full page layout contains all sections, related lists, and components. On mobile, action layouts load faster, require less scrolling, and are optimized for one-handed entry. Full page layouts are used when viewing/editing a full record."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s1-obj7",
                    title: "Describe the customizations and use cases for Chatter.",
                    topics: [
                        StudyTopic(id: "ab-s7-t1", number: 1, question: "How do you post to a record feed vs. a personal user feed vs. a Chatter group feed?", answer: "Record feed: post from the Chatter component on a record page — posts are visible to all users with access to that record. Personal user feed: post from your own profile page — visible to your followers. Chatter group feed: post inside a group — visible to group members. Each context scopes who can see the post and who gets notified."),
                        StudyTopic(id: "ab-s7-t2", number: 2, question: "What is Chatter and what core collaboration features does it provide?", answer: "Chatter is Salesforce's built-in enterprise social collaboration platform. Core features: record and user feeds, @mentions, file sharing, groups (public/private/broadcast/unlisted), polls, publisher actions, feed tracking (automated field-change posts), mobile notifications, and integration with Salesforce records. It enables contextual collaboration without leaving the CRM."),
                        StudyTopic(id: "ab-s7-t3", number: 3, question: "What are Chatter groups and what types of groups can be created (public, private, broadcast-only, unlisted)?", answer: "Public group: anyone in the org can see and join. Private group: membership requires approval; non-members cannot see content. Broadcast-only group: only group owners/managers can post; members can only read (good for announcements). Unlisted group: hidden from search; members must be invited; used for sensitive discussions. Customer groups also allow external users."),
                        StudyTopic(id: "ab-s7-t4", number: 4, question: "What is the Chatter @mention feature and which types of Salesforce entities can be mentioned?", answer: "@mentions in Chatter notify the mentioned entity and create a hyperlink in the post. You can @mention: users, Chatter groups, and (in some contexts) records. When a user is @mentioned, they receive a notification email and an in-app bell notification. @mentioning a group notifies all group members."),
                        StudyTopic(id: "ab-s7-t5", number: 5, question: "How can an administrator enable or disable Chatter for specific users or for the entire org?", answer: "Org-level: Chatter is enabled/disabled in Setup under 'Chatter Settings'. User-level: admins can disable Chatter for specific users by unchecking the 'Chatter' permission on their profile. Note that disabling Chatter org-wide also disables Feed Tracking and Chatter notifications for all users. Partial rollouts can be managed via profiles."),
                        StudyTopic(id: "ab-s7-t6", number: 6, question: "When would Chatter notifications be a more appropriate collaboration tool than standard Salesforce email alerts?", answer: "Chatter notifications are better when: the communication is contextual to a Salesforce record (keeps conversation in context), team members should be able to reply and thread the discussion, you want to avoid inbox overload with non-actionable alerts, or when @mentioning a group is more efficient than maintaining an email distribution list."),
                        StudyTopic(id: "ab-s7-t7", number: 7, question: "What is a Chatter publisher action and how is it different from a standard quick action?", answer: "A Chatter publisher action appears in the Chatter feed publisher (the '+' menu above the feed) and is designed for social/collaboration tasks like posting to a group or sharing a file. A standard quick action (in the action bar) is designed for CRM tasks like creating records or logging calls. Publisher actions are feed-centric; quick actions are record-centric."),
                        StudyTopic(id: "ab-s7-t8", number: 8, question: "What is the maximum number of fields that can be enabled for Chatter feed tracking per object?", answer: "Up to 20 fields per object can be enabled for Chatter Feed Tracking. When a tracked field changes on a record, a post is automatically added to that record's Chatter feed showing the old and new value. This makes it easy to see a record's history of changes without opening audit trails."),
                        StudyTopic(id: "ab-s7-t9", number: 9, question: "What is Chatter feed tracking, and how does an administrator configure which field changes are surfaced in a record's Chatter feed?", answer: "Feed tracking automatically posts a message to a record's Chatter feed whenever selected fields change. To configure: go to Setup > Feed Tracking, select the object, enable tracking, and check the specific fields to track (up to 20). Standard and custom fields are eligible. Changes show as 'Field changed from X to Y' posts, visible to all users with record access."),
                    ]
                )
            ]
        ),

        // Section 2: Data Modeling and Management (84 topics)
        StudySection(
            id: "ab-s2",
            title: "Data Modeling and Management",
            color: Color(red: 0.10, green: 0.50, blue: 0.55),
            lightColor: Color(red: 0.88, green: 0.96, blue: 0.97),
            icon: "cylinder.fill",
            objectives: [
                StudyObjective(
                    id: "ab-s2-obj1",
                    title: "Given a scenario, determine the appropriate data model.",
                    topics: [
                        StudyTopic(id: "ab-s8-t1", number: 1, question: "A business needs to associate multiple products with multiple campaigns, where each association tracks its own campaign-specific attributes. What data model satisfies this requirement?", answer: "Create a junction object (e.g., 'Campaign Product') with two master-detail relationships — one to Campaign and one to Product. Each junction record represents one Campaign-Product association and can hold its own fields (e.g., discount rate, start date). This is the standard many-to-many pattern in Salesforce."),
                        StudyTopic(id: "ab-s8-t2", number: 2, question: "What is a junction object and when is it used to model a many-to-many relationship?", answer: "A junction object is a custom object with two master-detail relationship fields pointing to two different parent objects. It represents the intersection in a many-to-many relationship. Each record on the junction represents one instance of the relationship between the two parents, plus any attributes specific to that pairing."),
                        StudyTopic(id: "ab-s8-t3", number: 3, question: "When should you create a custom object rather than extending a standard object?", answer: "Create a custom object when: the data does not semantically fit any standard object, the standard object's built-in behaviors (like Opportunity stages) don't apply, you need a separate tab/UI independent of standard objects, or the relationship structure requires a new entity. Extend a standard object (with custom fields) when the core data concept matches (e.g., adding fields to Contact)."),
                        StudyTopic(id: "ab-s8-t4", number: 4, question: "What is the maximum number of master-detail relationships a custom object can have?", answer: "A custom object can have a maximum of 2 master-detail relationships. This is a hard platform limit. This restriction exists because each master-detail relationship determines record ownership and OWD inheritance, and conflicting rules from two or more masters would create ambiguity."),
                        StudyTopic(id: "ab-s8-t5", number: 5, question: "A company wants to track individual line items for each order, where each line item cannot exist without an order. Which relationship type is most appropriate?", answer: "Use a master-detail relationship with Order as the master and Line Item as the child. Master-detail enforces that child records cannot exist without a parent (required relationship, no blank allowed), provides cascade delete (deleting the order deletes its line items), and enables roll-up summary fields on the parent."),
                        StudyTopic(id: "ab-s8-t6", number: 6, question: "What is the maximum number of custom objects allowed per Salesforce org (standard edition considerations)?", answer: "The limit varies by edition: Developer Edition allows up to 400 custom objects, Enterprise Edition up to 2,000, Unlimited Edition up to 2,000. Professional Edition is much lower (50-100 depending on add-ons). The exam typically focuses on the general concept that limits exist by edition, not on memorizing every number."),
                        StudyTopic(id: "ab-s8-t7", number: 7, question: "When is it appropriate to denormalize data into a formula field rather than maintaining a separate related object?", answer: "Denormalize into a formula field when: the value is always derivable from other fields on the same record or a parent record, the data is read-only and does not need to be stored independently, you want to avoid creating additional objects and relationships, and the calculation is simple enough for a formula. Avoid denormalization when the data needs independent lifecycle management."),
                        StudyTopic(id: "ab-s8-t8", number: 8, question: "What are record types and what three things do they control on an object: picklist values available to users, the page layout displayed, and the business process applied?", answer: "Record types control: (1) which picklist values are available to users (subset of the master picklist), (2) which page layout is displayed to users with that record type, and (3) which business process is applied (Sales Process for Opportunities, Support Process for Cases, Lead Process for Leads). A user's profile determines which record types they can create."),
                        StudyTopic(id: "ab-s8-t9", number: 9, question: "How are record types assigned to users, and which mechanism determines which record type(s) a specific user can create?", answer: "Record types are assigned through profiles and permission sets. In the profile (or permission set), you specify which record types on each object the user has access to, and which is the default. When a user creates a new record and has access to multiple record types, they are prompted to choose one. The profile/permission set assignment is the gatekeeper."),
                        StudyTopic(id: "ab-s8-t10", number: 10, question: "A company has two sales teams — Enterprise and SMB — that need different Stage picklist values and different page layouts on Opportunity records. What is the correct Salesforce feature to implement this?", answer: "Use Record Types on Opportunity object. Create two record types (Enterprise and SMB), each linked to a different Sales Process (controlling Stage values) and a different page layout. Assign each record type to the respective team's profiles. This is the canonical Salesforce solution for team-specific picklist values and layouts on the same object."),
                        StudyTopic(id: "ab-s8-t11", number: 11, question: "What is the Master record type and what is its behavior when a user's profile has no explicit record type assignment?", answer: "The Master record type is the system default that exists on every object automatically. It includes all picklist values and uses the object's default page layout. If a user's profile has no explicit record type assignment for an object, they receive the Master record type by default, seeing all picklist values and the master page layout."),
                        StudyTopic(id: "ab-s8-t12", number: 12, question: "What is a sales process in Salesforce and how does it control which Opportunity Stage values are available for a specific record type?", answer: "A Sales Process is a subset of Opportunity Stage picklist values curated for a specific business scenario. You create a Sales Process by selecting which Stage values from the master list to include. You then associate that Sales Process with a record type. Users with that record type can only see and select the Stage values in the linked Sales Process."),
                        StudyTopic(id: "ab-s8-t13", number: 13, question: "What is a custom metadata type and how does it differ from a custom object in terms of deployment, access in Apex, and use in validation rules?", answer: "Custom metadata type records are metadata — they are deployable via change sets and packages (unlike custom object data records). They can be referenced in formula fields, validation rules, and Flows natively. In Apex, they are queried with SOQL but are not subject to DML governor limits for reads. Custom object records are data — not deployable, not usable in validation formulas directly."),
                        StudyTopic(id: "ab-s8-t14", number: 14, question: "What is the difference between a Hierarchy custom setting and a List custom setting, and when would you use each?", answer: "Hierarchy custom setting: stores values at the org, profile, or user level — the most specific level wins. Ideal for feature flags or thresholds that may differ by user group. List custom setting: stores a simple name-value set (like a lookup table) accessible to any user. Use Hierarchy for user/profile-level overrides; use List for org-wide reference data that doesn't vary by user."),
                        StudyTopic(id: "ab-s8-t15", number: 15, question: "What is a support process and how does it define the Case Status picklist values for a specific Case record type?", answer: "A Support Process is analogous to a Sales Process but for Cases. It defines which Case Status picklist values (from the master list) are available for a given Case record type. For example, a Technical Support process might include 'Pending Engineering' while a Billing process would not. Assign the Support Process to the Case record type."),
                        StudyTopic(id: "ab-s8-t16", number: 16, question: "A business needs to store configurable threshold values (e.g., discount limits per product line) that can be referenced in validation rules, formulas, and Flows, and must be deployable via change sets. Which feature is most appropriate?", answer: "Custom Metadata Types. They are deployable via change sets and packages, can be referenced directly in formulas and validation rules (unlike custom settings in formulas), and are accessible in Flows. Custom settings are not directly referenceable in validation rule formulas. Custom objects require data migration, not metadata deployment."),
                        StudyTopic(id: "ab-s8-t17", number: 17, question: "Can custom metadata type records be deployed via change sets and packages, unlike custom object records which must be loaded separately?", answer: "Yes. Custom metadata type records are treated as metadata, not data. They travel with change sets and managed/unmanaged packages automatically. Custom object data records are data and must be migrated separately using Data Loader or similar tools. This is the key operational advantage of custom metadata types for configuration data."),
                        StudyTopic(id: "ab-s8-t18", number: 18, question: "Select two capabilities that custom metadata types have that regular custom objects do not, making them preferred for app configuration data.", answer: "Two key capabilities: (1) Records are deployable as metadata via change sets and packages — no separate data migration needed. (2) Records can be referenced directly in formula fields and validation rules using the $CustomMetadata merge field — custom object records cannot be referenced in validation rule formulas. Both make custom metadata types superior for app configuration."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s2-obj2",
                    title: "Given a scenario, explain the capabilities of the various relationship types and the implications of each on record access, user interface, and reporting.",
                    topics: [
                        StudyTopic(id: "ab-s9-t1", number: 1, question: "Can a master-detail relationship field be left blank on a child record?", answer: "No. A master-detail relationship field is always required on the child record. The child record cannot exist without a parent. This enforces referential integrity. If you need an optional parent relationship, use a lookup relationship instead."),
                        StudyTopic(id: "ab-s9-t2", number: 2, question: "What happens to child records when a master record in a master-detail relationship is deleted?", answer: "Child records are cascade deleted when the master is deleted. This is automatic and cannot be prevented by configuration. If you need child records to survive parent deletion, use a lookup relationship instead. The cascade delete also fires any before/after delete triggers on the child records."),
                        StudyTopic(id: "ab-s9-t3", number: 3, question: "What happens to child records when a parent record in a lookup relationship is deleted?", answer: "In a lookup relationship, child records are NOT automatically deleted when the parent is deleted. Depending on the 'What to do if the lookup record is deleted' setting, the lookup field is either cleared (set to blank) or the deletion is blocked. No cascade delete occurs. Child records survive independently."),
                        StudyTopic(id: "ab-s9-t4", number: 4, question: "Can a lookup relationship field be left blank on a child record?", answer: "Yes, by default. Lookup relationship fields are optional — the child record can exist with no parent specified. However, you can make a lookup field required on the page layout or at the field definition level to enforce that a parent must be selected. This still does not create cascade delete behavior."),
                        StudyTopic(id: "ab-s9-t5", number: 5, question: "How does record sharing work for child records in a master-detail relationship vs. a lookup relationship?", answer: "Master-detail: child records inherit the sharing and OWD of the master record — they don't have independent sharing. Lookup: child records have their own OWD and sharing model independently of the parent. This means in a master-detail, securing the parent automatically secures children; in a lookup, each object's sharing is configured separately."),
                        StudyTopic(id: "ab-s9-t6", number: 6, question: "How does a master-detail relationship affect the ownership of child records?", answer: "In a master-detail relationship, the child record does not have its own Owner field — ownership is inherited from the master record. The master's owner is the effective owner of all child records. In a lookup relationship, child records have their own Owner field and ownership is independent of the parent."),
                        StudyTopic(id: "ab-s9-t7", number: 7, question: "On which relationship type can roll-up summary fields be created — master-detail or lookup?", answer: "Roll-up summary fields can only be created on the master record in a master-detail relationship. They aggregate child record values (COUNT, SUM, MIN, MAX) up to the parent. Lookup relationships do not support roll-up summary fields natively. (Lookups can use cross-object formula fields, but not roll-up summaries.)"),
                        StudyTopic(id: "ab-s9-t8", number: 8, question: "Can a master-detail child record be reparented (reassigned to a different parent)?", answer: "Yes, but only if the master object allows reparenting. By default, master-detail child records can be reparented — the 'Allow reparenting' option on the relationship field must be enabled. If disabled (the default before Summer '12), child records cannot change their master. Reparenting changes the child's effective owner and sharing to match the new master."),
                        StudyTopic(id: "ab-s9-t9", number: 9, question: "What is a hierarchical relationship field and which standard object uses it?", answer: "A hierarchical relationship is a special lookup relationship where a record can look up to another record of the same object, creating a tree structure. It is only available on the User standard object (the 'Manager' field is a hierarchical relationship). It cannot be created on custom objects."),
                        StudyTopic(id: "ab-s9-t10", number: 10, question: "What is a self-relationship (lookup to the same object) and what is a common use case for it?", answer: "A self-relationship is a lookup field on an object that points to another record of the same object. Common use case: an Account 'Parent Account' field (a lookup to Account itself) to model a corporate hierarchy. Another example: an 'Escalated From' field on Case pointing to another Case. These create hierarchical or associative structures within a single object."),
                        StudyTopic(id: "ab-s9-t11", number: 11, question: "A business needs both cascade delete behavior and roll-up summaries on a child object. Which relationship type must be used?", answer: "Master-detail relationship. Both cascade delete and roll-up summary fields are exclusive to master-detail relationships. If either of these features is required, the relationship must be master-detail. Lookup relationships support neither capability."),
                        StudyTopic(id: "ab-s9-t12", number: 12, question: "What is the maximum number of lookup relationships a single custom object can have?", answer: "A custom object can have up to 25 lookup relationships (in addition to the 2 master-detail relationships). This limit rarely becomes an issue in practice, but it is good to know for the exam. Each lookup adds a field on the child object pointing to a parent record."),
                        StudyTopic(id: "ab-s9-t13", number: 13, question: "What are the reporting implications of a master-detail vs. a lookup relationship when creating standard reports?", answer: "Master-detail: roll-up summaries on the parent can be reported on; standard report types include both parent and child data naturally. Lookup: no roll-up summary fields, so parent-level aggregation must use cross-object formulas or custom report types. Both relationship types appear in standard report types, but roll-up fields only exist for master-detail."),
                        StudyTopic(id: "ab-s9-t14", number: 14, question: "A developer is deciding between a master-detail and a lookup relationship for a new child object. Select two capabilities that are ONLY available with a master-detail relationship.", answer: "Two master-detail-only capabilities: (1) Roll-up summary fields on the parent (COUNT, SUM, MIN, MAX of child values). (2) Cascade delete — deleting the parent automatically deletes all child records. Both are critical for data integrity and aggregation scenarios. Lookup relationships offer neither."),
                        StudyTopic(id: "ab-s9-t15", number: 15, question: "In a junction object that has two master-detail relationship fields pointing to two different parent objects, how is record ownership determined and which parent's OWD governs access to the junction record?", answer: "The junction record's access is governed by the more permissive of the two parent OWDs. For example, if Parent A is Private and Parent B is Public Read Only, a user who has access to either parent can access the junction record. Ownership of the junction record belongs to the user who created it (or the record owner), but sharing follows the most permissive parent."),
                        StudyTopic(id: "ab-s9-t16", number: 16, question: "What is a lookup filter on a relationship field and how does it restrict which records a user can select in the lookup?", answer: "A lookup filter restricts the records shown in the lookup search dialog based on field criteria. For example, a Contact lookup on Opportunity filtered to show only Contacts related to the same Account. Filters can be based on fields on the source record, the target object's fields, or running user attributes. This prevents incorrect parent selections."),
                        StudyTopic(id: "ab-s9-t17", number: 17, question: "What is the difference between a required lookup filter and an optional lookup filter, and how does each behave when the user selects a value that does not match the filter?", answer: "Required filter: only matching records appear in search; the user cannot select a non-matching record — the system blocks the save with an error. Optional filter: only matching records appear by default, but the user can override the filter and search for all records. A required filter is an enforcement mechanism; optional is a convenience filter."),
                        StudyTopic(id: "ab-s9-t18", number: 18, question: "How are related lists displayed differently in the UI for master-detail vs. lookup relationships?", answer: "Both master-detail and lookup relationships create a related list on the parent record's page layout. However, master-detail related lists include a 'New [Child Object]' button by default (because the child requires a parent). Lookup related lists also include the 'New' button, but the child can potentially exist without the parent. Functionally the display is similar, but cascade behavior differs."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s2-obj3",
                    title: "Given a scenario, determine the considerations when selecting or changing a field data type.",
                    topics: [
                        StudyTopic(id: "ab-s10-t1", number: 1, question: "What is the maximum character length of a standard Text field in Salesforce?", answer: "A standard Text field supports up to 255 characters. If more text is needed, use Text Area (up to 255 chars with line breaks), Text Area (Long) up to 131,072 chars, or Text Area (Rich) up to 131,072 chars with HTML formatting. Choose the field type based on the data length and formatting needs."),
                        StudyTopic(id: "ab-s10-t2", number: 2, question: "What is an auto-number field and when would you use one?", answer: "An auto-number field automatically generates a unique, sequential ID for each record (e.g., CASE-0001, CASE-0002). Use it for: record numbering systems (ticket numbers, invoice IDs, case numbers), unique identifiers that must be human-readable and sequential, and external references. Auto-number fields are read-only, cannot be edited, and are always unique."),
                        StudyTopic(id: "ab-s10-t3", number: 3, question: "What is the difference between a Number field, a Currency field, and a Percent field in Salesforce?", answer: "Number: stores a pure numeric value with no currency or percentage symbol. Currency: stores a monetary value, respects the org's currency locale, and displays the currency symbol. Supports multi-currency. Percent: stores a numeric value and displays it with a % sign, but the stored value is the raw number (e.g., 50 displays as 50%). All three support decimal places."),
                        StudyTopic(id: "ab-s10-t4", number: 4, question: "What is the formula field character (compile size) limit?", answer: "A formula field has a maximum compile size of 5,000 characters (not the text you type, but the compiled formula after expansion of referenced formulas). The raw formula you write is limited to 3,900 characters. This is why deeply nested formulas or formulas that reference many other formula fields can fail to save — they exceed the compile size."),
                        StudyTopic(id: "ab-s10-t5", number: 5, question: "What data types can be marked as External ID on a Salesforce object?", answer: "External ID can be enabled on: Text, Number, Email, and Auto Number field types. The External ID checkbox makes the field indexed for faster querying and enables upsert operations in Data Loader and the API. Each object can have up to 25 External ID fields. Only fields on custom objects can be set as External ID (some standard fields are already External IDs by design)."),
                        StudyTopic(id: "ab-s10-t6", number: 6, question: "What are the implications of changing a Text field to a Picklist field (data loss, existing values)?", answer: "Changing Text to Picklist does not delete existing data, but existing text values that don't match any picklist value will become invalid picklist entries. Salesforce displays them as stale values. If 'Restrict picklist to the values in the value set' is enabled, reports and validation rules may reject these stale values. Always review existing data before converting."),
                        StudyTopic(id: "ab-s10-t7", number: 7, question: "What happens to existing data when you change a Number field to a Text field?", answer: "Existing numeric data is preserved but converted to text representation. The field type change does not erase data. However, the field can no longer be used in numeric calculations, roll-up summaries, or range filters after the change. Reports and formulas that referenced the field as a number will need to be updated."),
                        StudyTopic(id: "ab-s10-t8", number: 8, question: "What is the difference between a Text Area and a Text Area (Rich) field in Salesforce?", answer: "Text Area: allows multi-line plain text up to 255 characters, no formatting. Text Area (Rich): allows HTML-formatted text (bold, italic, bullet lists, hyperlinks, images) up to 131,072 characters. Rich text is rendered in the UI as formatted HTML. Text Area (Rich) fields cannot be used in formula fields, report filters, or standard SOQL WHERE clauses."),
                        StudyTopic(id: "ab-s10-t9", number: 9, question: "What are the limitations of a Text Area (Rich) field when used in formula fields and report filters?", answer: "Text Area (Rich) fields cannot be referenced in formula fields at all. They cannot be used as report filter criteria. They are also not searchable via standard SOQL WHERE clause equality filters. These limitations exist because the field stores HTML content, which is not conducive to exact-match comparisons or formula calculations."),
                        StudyTopic(id: "ab-s10-t10", number: 10, question: "What is the maximum number of custom fields allowed per standard or custom object?", answer: "The maximum is 500 custom fields per object for Enterprise and Unlimited editions. This includes all custom field types — text, number, formula, etc. Developer Edition has lower limits. This limit encourages thoughtful data modeling rather than creating fields indiscriminately."),
                        StudyTopic(id: "ab-s10-t11", number: 11, question: "A field currently stores unformatted text but users now need to enter formatted content with bullets and links. Which field type should it be changed to?", answer: "Change it to Text Area (Rich). This field type supports HTML formatting including bullet lists, hyperlinks, bold/italic, and image embedding. Remember the trade-offs: Rich text fields cannot be used in formulas or report filters. If the field is already used in formulas or reports as a filter, that usage must be redesigned."),
                        StudyTopic(id: "ab-s10-t12", number: 12, question: "When would you choose a Checkbox field over a Required Picklist with Yes/No values?", answer: "Use a Checkbox when the answer is strictly binary (true/false, yes/no) and you want a compact, clear UI element. Checkbox fields default to 'false' (unchecked), are never null, and work cleanly in boolean formula logic. A Yes/No picklist has three states (Yes, No, blank), which adds complexity. Checkboxes are preferred for simple boolean flags."),
                        StudyTopic(id: "ab-s10-t13", number: 13, question: "What is the difference between a Date field and a Date/Time field, and when does the distinction matter in formulas?", answer: "Date stores only a calendar date (no time component). Date/Time stores both date and time, stored in UTC and displayed in the user's time zone. The distinction matters in formulas when calculating differences: DATE - DATE returns a number (days); DATETIMEVALUE operations must account for time zones. Use Date for birthdays or deadlines; use Date/Time for events, timestamps, or SLA calculations."),
                        StudyTopic(id: "ab-s10-t14", number: 14, question: "What field type should be used to store a unique integration ID from an external system that will be used for upsert operations?", answer: "Use a Text field with the 'External ID' checkbox enabled and 'Unique' checkbox enabled. This allows the field to be used as an upsert key in Data Loader and the API. External ID + Unique ensures no duplicate integration IDs exist, and the field is indexed for fast lookup during upsert matching."),
                        StudyTopic(id: "ab-s10-t15", number: 15, question: "An admin is considering changing a custom field from Text to Picklist. Select two consequences that will occur as a result of this field type change.", answer: "Two consequences: (1) Existing text values in the field will not automatically match any picklist value — they become stale/invalid picklist entries that display but may cause issues in validation and reporting. (2) If 'Restrict picklist to value set' is enabled, those stale values will fail validation on save. Data cleanup is needed post-conversion."),
                        StudyTopic(id: "ab-s10-t16", number: 16, question: "What is the INCLUDES() formula function and when is it required instead of ISPICKVAL() when referencing a multi-select picklist field?", answer: "INCLUDES() is required for multi-select picklist fields. It checks whether a specific value is among the selected values in a multi-select picklist. ISPICKVAL() only works with single-value picklist fields. Since multi-select picklists store a semicolon-delimited string of values, INCLUDES() parses that string correctly. Example: INCLUDES(Multi_Select_Field__c, 'Option A')."),
                        StudyTopic(id: "ab-s10-t17", number: 17, question: "What is the maximum number of fields per object that can be enabled for field history tracking?", answer: "A maximum of 20 fields per object can be enabled for field history tracking. History data is retained for 18 months (or longer with a data archive add-on). Field history tracking records who changed a field, when, and from what value to what value — viewable in the History related list on the record."),
                        StudyTopic(id: "ab-s10-t18", number: 18, question: "What is a multi-select picklist field and what are its key limitations in reports (cannot group by, cannot use standard filters) and formula fields?", answer: "A multi-select picklist allows users to select multiple values from a list. Key limitations: in reports, you cannot group by a multi-select picklist field, and standard filter operators (equals, contains) do not work as expected. In formulas, you must use INCLUDES() to check for a value. ISPICKVAL() does not work. These constraints make multi-select picklists harder to report on and automate."),
                        StudyTopic(id: "ab-s10-t19", number: 19, question: "What is a global picklist value set and how does it differ from the values defined locally on an individual picklist field?", answer: "A global picklist value set is a centrally managed list of values that multiple picklist fields across different objects can share. Changes to the global set propagate to all fields using it. A locally defined picklist has its own values managed independently. Use global picklists for consistency (e.g., a standard 'Region' list used across Accounts, Opportunities, and Cases)."),
                        StudyTopic(id: "ab-s10-t20", number: 20, question: "What is a geolocation field type, what does it store, and what is a common declarative use case for it?", answer: "A geolocation field stores latitude and longitude coordinates. Declarative use cases: calculating distance between records using the DISTANCE() and GEOLOCATION() formula functions, proximity-based list view filters, and mapping integrations. For example, finding all Accounts within 50 miles of a given location using a report filter or formula."),
                        StudyTopic(id: "ab-s10-t21", number: 21, question: "When values are added to or removed from a global picklist value set, which picklist fields that reference that set are automatically updated?", answer: "All picklist fields that reference the global value set are automatically updated when values are added or removed from the set. This is the key operational benefit of global value sets — one change propagates everywhere. However, removing a value from a global set may leave existing records with stale values, so data impact assessment is important."),
                        StudyTopic(id: "ab-s10-t22", number: 22, question: "What is a field dependency (dependent picklist) and what are the roles of the controlling field versus the dependent field?", answer: "A field dependency links two fields so the values available in the dependent field are filtered based on the value selected in the controlling field. Controlling field: drives which values appear in the dependent field (must be a picklist or checkbox). Dependent field: shows only the values mapped to the controlling field's selected value. Example: selecting 'Country' filters which 'State' values appear."),
                        StudyTopic(id: "ab-s10-t23", number: 23, question: "Which field types can serve as a controlling field in a field dependency?", answer: "Controlling fields must be either a standard or custom picklist field (single-select) or a checkbox field. Multi-select picklists cannot be controlling fields. The controlling field drives the filtering logic for the dependent field. Radio button-style picklists and checkboxes are the only supported controlling field types."),
                        StudyTopic(id: "ab-s10-t24", number: 24, question: "Which field types can serve as a dependent field in a field dependency?", answer: "Dependent fields must be picklist fields (single-select) or multi-select picklist fields. Text fields, numbers, and other field types cannot be dependent fields. The values shown in the dependent field are filtered by what is mapped in the dependency matrix to the controlling field's selected value."),
                        StudyTopic(id: "ab-s10-t25", number: 25, question: "When a record type is applied to an object, what controls which picklist values are available to users assigned that record type?", answer: "The record type's picklist value configuration controls this. In each record type, an admin selects a subset of the master picklist values for each picklist field. Users assigned that record type only see those selected values. This is separate from field dependencies — record types filter by user persona, dependencies filter by another field's value."),
                        StudyTopic(id: "ab-s10-t26", number: 26, question: "A company needs the 'Product Family' picklist to filter which values appear in the 'Product Sub-type' picklist on the same record. Which feature implements this?", answer: "Field Dependencies (dependent picklists). Make 'Product Family' the controlling field and 'Product Sub-type' the dependent field. In the dependency matrix, map which Sub-type values should be available for each Product Family value. When the user selects a Product Family, only the relevant Sub-type values appear."),
                        StudyTopic(id: "ab-s10-t27", number: 27, question: "What is field history tracking and what types of field changes does it capture on a Salesforce record?", answer: "Field history tracking automatically logs changes to enabled fields. For each change it captures: the date/time of the change, the user who made it, the old value, and the new value. It is viewable in the '[Object] History' related list. It supports up to 20 fields per object and retains data for 18 months. It tracks changes from UI, API, automation, and imports."),
                        StudyTopic(id: "ab-s10-t28", number: 28, question: "What does marking a field 'Required' at the field definition level mean, and in which save contexts (API, Flow, page layout) does it enforce a value?", answer: "Marking a field Required at the field level (in field setup) makes it mandatory in every save context — UI, API, and automation (Flow, Apex, Data Loader). No record can be saved without a value, regardless of how the save is initiated. This is the strongest enforcement level and is appropriate when the field is always business-critical."),
                        StudyTopic(id: "ab-s10-t29", number: 29, question: "What does marking a field 'Required' on a page layout mean, and how does this differ from the field definition level requirement?", answer: "Marking a field Required on a page layout only enforces the value when a user saves through that specific page layout in the UI. API calls, Flows, and other automated saves that bypass the page layout are NOT affected. This is a UI-only enforcement. Use this when the field is contextually required for a specific user workflow but not universally mandatory."),
                        StudyTopic(id: "ab-s10-t30", number: 30, question: "When should you enforce a field as required using a validation rule rather than at the field definition level or on a page layout?", answer: "Use a validation rule for conditional requirements — for example, 'Close Date is required only when Stage = Closed Won.' Field-level requirement is unconditional (always required). Page layout requirement is layout-context-only. Validation rules are the only mechanism that can enforce conditional field requirements across all save contexts (UI and API)."),
                        StudyTopic(id: "ab-s10-t31", number: 31, question: "If a field is marked Required on a page layout but not at the field definition level, what happens when the record is saved via an API call or a Flow that does not include that field?", answer: "The record saves successfully without a value in that field. Page layout requirements only apply to UI-based saves through that specific layout. API and Flow saves bypass page layouts entirely. If enforcement across all save contexts is needed, either mark the field Required at the field definition level or write a validation rule."),
                        StudyTopic(id: "ab-s10-t32", number: 32, question: "What is the maximum character length of a Text Area (Long) field in Salesforce?", answer: "A Text Area (Long) field supports up to 131,072 characters (128 KB). This makes it suitable for storing large blocks of plain text such as notes, descriptions, or log data. Unlike Rich Text, it does not support HTML formatting but can be used in more formula and automation contexts."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s2-obj4",
                    title: "Explain the capabilities and considerations of the Schema Builder.",
                    topics: [
                        StudyTopic(id: "ab-s11-t1", number: 1, question: "What can be accomplished in Schema Builder that is also possible through standard Setup object management?", answer: "Schema Builder allows you to: create new custom objects, create new custom fields on existing objects, define relationships between objects, and view field properties. All of these actions are also available through individual object management pages in Setup. Schema Builder just provides a visual canvas instead of navigating menus."),
                        StudyTopic(id: "ab-s11-t2", number: 2, question: "What actions CANNOT be performed in Schema Builder (e.g., deleting fields, managing field dependencies, creating custom settings)?", answer: "Schema Builder cannot: delete fields or objects, manage field dependencies (dependent picklists), create or manage custom settings or metadata types, configure validation rules, configure page layouts, or manage picklist values. For these tasks, you must navigate to the individual object's setup page."),
                        StudyTopic(id: "ab-s11-t3", number: 3, question: "Can you create new custom objects and fields directly from the Schema Builder canvas?", answer: "Yes. You can drag a new object onto the Schema Builder canvas to create it, and you can add fields to existing objects by clicking the object and using the 'Add fields' option. Relationship fields (lookup and master-detail) can also be created by drawing a line between objects on the canvas. This is one of Schema Builder's most useful features for rapid prototyping."),
                        StudyTopic(id: "ab-s11-t4", number: 4, question: "What is the primary use case for using Schema Builder over individual object management pages in Setup?", answer: "The primary use case is visualizing and understanding a complex data model. Schema Builder displays all objects and their relationships on one canvas, making it easy to see the full entity-relationship diagram. This is especially valuable when reviewing an unfamiliar org or planning changes to a multi-object data model without navigating dozens of separate Setup pages."),
                        StudyTopic(id: "ab-s11-t5", number: 5, question: "How does Schema Builder help a developer or admin understand a complex data model with many relationships?", answer: "Schema Builder renders objects as entity boxes connected by relationship lines (master-detail and lookup). You can filter which objects to display, zoom in/out, and drag objects around the canvas. This visual representation immediately shows how objects relate — which is a master, which has lookup relationships, and the cardinality of each relationship — far faster than reading object setup pages individually."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s2-obj5",
                    title: "Given a scenario, determine the options and considerations when importing and exporting data, including the capabilities of external data sources.",
                    topics: [
                        StudyTopic(id: "ab-s12-t1", number: 1, question: "What is the Data Import Wizard and what types of standard objects does it support natively?", answer: "The Data Import Wizard is a browser-based import tool in Setup. It natively supports: Accounts, Contacts, Leads, Solutions, Campaign Members, and custom objects. It does not support all standard objects (e.g., Opportunities, Cases are not supported). It is simple to use, has a guided interface, and handles duplicate matching via matching rules."),
                        StudyTopic(id: "ab-s12-t2", number: 2, question: "What is the maximum record count supported by the Data Import Wizard in a single import?", answer: "The Data Import Wizard supports up to 50,000 records per import file. For larger volumes, Data Loader or Bulk API must be used. The 50,000 record limit makes the Import Wizard suitable for moderate data imports but inadequate for large-scale migrations."),
                        StudyTopic(id: "ab-s12-t3", number: 3, question: "How does Data Loader differ from the Data Import Wizard in terms of record volume, object support, and automation?", answer: "Data Loader: supports up to 5 million records per operation, works with all standard and custom objects, supports all DML operations (insert, update, upsert, delete, hard delete, export), can be run via command line for automation, and requires a desktop installation. Data Import Wizard: browser-based, max 50,000 records, limited object support, no automation capability."),
                        StudyTopic(id: "ab-s12-t4", number: 4, question: "What is the difference between a hard delete and a soft delete when using Data Loader?", answer: "Soft delete (standard delete): moves records to the Recycle Bin, where they can be restored within 15 days. Hard delete: permanently removes records, bypassing the Recycle Bin. Hard delete requires the 'Hard Delete' permission on the user's profile. Hard deleted records cannot be recovered and free up data storage immediately."),
                        StudyTopic(id: "ab-s12-t5", number: 5, question: "What is an external object in Salesforce and how does it differ from a custom object?", answer: "An external object is a Salesforce object that maps to data stored in an external system (outside Salesforce) via Salesforce Connect and OData or custom adapters. Data is accessed in real time — not stored in Salesforce. A custom object stores data natively in Salesforce's database. External objects are used when you want to view external data in Salesforce without importing and storing it."),
                        StudyTopic(id: "ab-s12-t6", number: 6, question: "What is Salesforce Connect and what does it enable in terms of accessing external data?", answer: "Salesforce Connect is a middleware feature that allows Salesforce to display data from external systems in real time without storing it in Salesforce. It uses OData protocol or custom adapters. Data appears as external objects in Salesforce with related lists, list views, and record detail pages — but the data lives in the external system. Ideal for read-heavy, real-time integration needs."),
                        StudyTopic(id: "ab-s12-t7", number: 7, question: "What is an External ID field and how is it used during an upsert operation in Data Loader?", answer: "An External ID field is a custom field with the External ID checkbox enabled, making it an indexed unique identifier from an external system. During an upsert operation in Data Loader, you specify the External ID field as the match key. If a record with that External ID value exists, it is updated; if not, a new record is inserted. This prevents duplicates during repeated imports."),
                        StudyTopic(id: "ab-s12-t8", number: 8, question: "A company needs to import 200,000 account records from an external system. Which tool should be used?", answer: "Data Loader. The Data Import Wizard is limited to 50,000 records and does not support Accounts in all scenarios cleanly at scale. Data Loader handles up to 5 million records, supports Account imports fully, and can be run in batch mode via command line. For 200,000 records, Data Loader is the appropriate tool."),
                        StudyTopic(id: "ab-s12-t9", number: 9, question: "What is a matching rule and how does it work with duplicate rules to prevent data duplication?", answer: "A matching rule defines the logic for identifying potential duplicate records (e.g., match on Email + Last Name + Company). A duplicate rule uses matching rules to determine what happens when a match is found — either alert the user, block the save, or allow with a warning. Together, they form Salesforce's native duplicate management framework."),
                        StudyTopic(id: "ab-s12-t10", number: 10, question: "What duplicate management features exist in Salesforce for handling duplicate records during import?", answer: "Salesforce provides: (1) Matching Rules — define what fields constitute a match, (2) Duplicate Rules — define the action when a match is found (block, alert, allow), (3) Duplicate Jobs — a batch process that scans existing data for duplicates and surfaces them for review. Data Import Wizard also has built-in duplicate handling using matching rules."),
                        StudyTopic(id: "ab-s12-t11", number: 11, question: "What is the Data Export Service in Salesforce Setup and what are the two available export frequency options?", answer: "The Data Export Service allows full org data exports as ZIP files of CSV data. It is available in Setup under Data > Data Export. Two frequency options: Weekly (export every 7 days) and Monthly (export once per month, typically on a scheduled date). Enterprise and Unlimited editions support weekly exports; lower editions are limited to monthly. Exports include all standard and custom object data."),
                    ]
                )
            ]
        ),

        // Section 3: Business Logic and Process Automation (90 topics)
        StudySection(
            id: "ab-s3",
            title: "Business Logic and Process Automation",
            color: Color(red: 0.15, green: 0.55, blue: 0.40),
            lightColor: Color(red: 0.88, green: 0.96, blue: 0.92),
            icon: "bolt.fill",
            objectives: [
                StudyObjective(
                    id: "ab-s3-obj1",
                    title: "Given a scenario, demonstrate the use of formula fields to meet stated business requirements.",
                    topics: [
                        StudyTopic(id: "ab-s13-t1", number: 1, question: "What is the IF() function in a formula field and how is it structured?", answer: "IF(logical_test, value_if_true, value_if_false). It evaluates a condition and returns one of two values. Example: IF(Amount > 100000, 'High Value', 'Standard'). The return type must be consistent across both branches (both text, both number, etc.). IF() can be nested for multiple conditions, though CASE() is cleaner for many discrete values."),
                        StudyTopic(id: "ab-s13-t2", number: 2, question: "What is the difference between the TODAY() and NOW() formula functions?", answer: "TODAY() returns the current date (no time component) as a Date value. NOW() returns the current date and time as a DateTime value in UTC. Use TODAY() for date arithmetic (days until close, days since created). Use NOW() when time precision matters (SLA violations calculated in hours/minutes). Mixing Date and DateTime in formulas causes errors."),
                        StudyTopic(id: "ab-s13-t3", number: 3, question: "What is the CASE() function in a formula field and how does it differ from nested IF() statements?", answer: "CASE(expression, value1, result1, value2, result2, ..., else_result) compares an expression against a list of discrete values and returns the matching result. It is cleaner and more readable than deeply nested IF() for multiple exact-match scenarios (like translating picklist values to text labels). IF() is better for range-based or boolean conditions."),
                        StudyTopic(id: "ab-s13-t4", number: 4, question: "What is the difference between ISNULL() and ISBLANK() in formula fields?", answer: "ISNULL() checks if a field is null — but for text fields, it returns false even for empty strings (because empty string != null in Salesforce). ISBLANK() checks for both null AND empty string, making it the correct function for text fields. For non-text fields (number, date, checkbox), both behave the same. Best practice: use ISBLANK() for text fields always."),
                        StudyTopic(id: "ab-s13-t5", number: 5, question: "What is the BLANKVALUE() function and when should it be used instead of ISNULL()?", answer: "BLANKVALUE(field, replacement_value) returns the replacement value if the field is blank or null, otherwise returns the field value. Use it instead of ISNULL() for text fields because BLANKVALUE() treats both null and empty string as blank. Example: BLANKVALUE(Phone, 'N/A') returns 'N/A' if Phone is blank, otherwise returns the phone number."),
                        StudyTopic(id: "ab-s13-t6", number: 6, question: "What does the NULLVALUE() function do and when would you use it over BLANKVALUE()?", answer: "NULLVALUE(field, replacement_value) returns the replacement value only if the field is null, not if it is an empty string. Use NULLVALUE() for non-text fields (numbers, dates, checkboxes) where null is the only 'no value' state. For text fields, BLANKVALUE() is the safer choice since it handles both null and empty string."),
                        StudyTopic(id: "ab-s13-t7", number: 7, question: "What is the ISPICKVAL() function and when is it required in a formula instead of a direct equality comparison?", answer: "ISPICKVAL(picklist_field, 'value') is required when comparing a single-value picklist field to a specific value in a formula. You cannot use picklist_field = 'value' directly in formulas. ISPICKVAL() correctly handles the picklist data type. Example: ISPICKVAL(Stage, 'Closed Won'). For multi-select picklists, use INCLUDES() instead."),
                        StudyTopic(id: "ab-s13-t8", number: 8, question: "What is the maximum compile size (character limit) for a formula field?", answer: "The maximum compile size for a formula field is 5,000 characters. This is the size after all referenced formula fields are expanded inline. The raw formula text you write is limited to 3,900 characters. Large formulas that reference many other formulas may hit the 5,000 compile limit even if the source text is under 3,900 characters."),
                        StudyTopic(id: "ab-s13-t9", number: 9, question: "What is the TEXT() function used for in a formula field?", answer: "TEXT() converts a non-text value (picklist, date, date/time, number, currency) into a text string so it can be concatenated with other text or used in text-returning formulas. Example: 'Stage: ' & TEXT(Stage) converts the picklist value to text. Without TEXT(), you cannot concatenate a picklist or number directly with a text literal."),
                        StudyTopic(id: "ab-s13-t10", number: 10, question: "What is the maximum number of unique cross-object relationships that can be referenced in a single formula field?", answer: "A formula field can reference up to 10 unique relationships (cross-object hops). This means you can traverse up to 10 different parent-child links in a single formula. Additionally, formulas can only traverse up to 5 levels deep in a single relationship chain. These limits prevent formula fields from becoming excessively resource-intensive."),
                        StudyTopic(id: "ab-s13-t11", number: 11, question: "A formula must display a picklist field's value as part of a text string. Which function is required to convert the picklist value to text?", answer: "The TEXT() function is required. Picklist fields are not text data types in formulas — they are a special picklist type. To concatenate a picklist value into a text string or return it from a text-returning formula, you must wrap it with TEXT(). Example: 'Current Status: ' & TEXT(Status__c)."),
                        StudyTopic(id: "ab-s13-t12", number: 12, question: "What is the IMAGE() formula function and when would you use it on a record?", answer: "IMAGE(image_url, alt_text, height, width) embeds an image (from a URL) in a formula field result on a record. Use it to display icons, color-coded status indicators, or thumbnail images based on field values. Example: use IMAGE() to show a red/yellow/green traffic light icon based on a risk score. The formula field return type must be Text for IMAGE() to work."),
                        StudyTopic(id: "ab-s13-t13", number: 13, question: "What is the HYPERLINK() formula function used for and what parameters does it require?", answer: "HYPERLINK(url, friendly_name, target) creates a clickable hyperlink in a formula field. Parameters: url (the destination URL, can use field merge syntax), friendly_name (display text), target (optional: '_blank' opens in new tab, '_self' in same window). Use it to create links to external systems, record pages, or filtered views directly from a record."),
                        StudyTopic(id: "ab-s13-t14", number: 14, question: "Can a formula field reference a field on a related (parent) object, and what is the syntax for doing so?", answer: "Yes. For lookup relationships, the syntax is: Object__r.Field__c (using __r to traverse the relationship). For standard relationships, use the relationship name (e.g., Account.Industry for a Contact's parent Account). This is called a cross-object formula. You can traverse up to 5 levels deep and reference up to 10 unique relationships per formula."),
                        StudyTopic(id: "ab-s13-t15", number: 15, question: "What formula function returns the number of days between two Date fields?", answer: "Simple subtraction: Date2 - Date1 returns the number of days as a number. There is no special function — Salesforce Date arithmetic directly supports subtraction of two Date values. Example: CloseDate - TODAY() returns the number of days until close. For Date/Time subtraction, the result is in fractional days (divide by 1 for days, multiply by 24 for hours)."),
                        StudyTopic(id: "ab-s13-t16", number: 16, question: "What return data types can a formula field produce?", answer: "Formula fields can return: Text, Number, Currency, Percent, Date, Date/Time, Checkbox (Boolean), and URL. The selected return type determines which functions and operators are valid in the formula and how the result is displayed and used in reports, filters, and automation."),
                        StudyTopic(id: "ab-s13-t17", number: 17, question: "A business requires a formula that returns different text values based on a numeric range. Which function is best suited for this (CASE vs. IF vs. nested IF)?", answer: "Nested IF() is best for numeric range conditions because CASE() only works with exact-match equality checks. For ranges like 'if score > 80, then Excellent; if > 60, then Good; else Needs Work,' nested IF() handles the range comparisons correctly. CASE() cannot evaluate greater-than or less-than conditions."),
                        StudyTopic(id: "ab-s13-t18", number: 18, question: "What is the LEN() formula function and when would you use it in a validation or formula context?", answer: "LEN(text) returns the number of characters in a text string. Use it in validation rules to enforce minimum/maximum text length (e.g., REQUIRE that a description is at least 50 characters: LEN(Description__c) < 50). In formula fields, use it to display text length or conditionally evaluate fields based on character count."),
                        StudyTopic(id: "ab-s13-t19", number: 19, question: "What is the CONTAINS() function in a formula and what data type does it return?", answer: "CONTAINS(text, search_string) returns a Boolean (TRUE or FALSE). It checks whether the text field contains the search string anywhere within it (case-insensitive in most contexts). Use it in validation rules and IF() conditions to check for substring presence. Example: CONTAINS(Email__c, '@company.com') to validate internal email addresses."),
                        StudyTopic(id: "ab-s13-t20", number: 20, question: "What is the BEGINS() formula function and how does it differ from CONTAINS()?", answer: "BEGINS(text, search_string) returns TRUE if the text starts with the search_string. CONTAINS() checks anywhere in the string. Use BEGINS() when you need to validate a prefix (e.g., phone numbers starting with '+1') or categorize records based on the start of a code. Both return Boolean and are usable in IF() and validation rules."),
                        StudyTopic(id: "ab-s13-t21", number: 21, question: "An admin is building a formula field that must handle both empty text fields and null values safely. Select two functions that address blank/null handling in formula fields.", answer: "Two functions: (1) ISBLANK() — returns TRUE if the text field is null OR empty string, safe for text fields. (2) BLANKVALUE(field, default) — returns a default value when the field is null or empty string. Together these cover all blank/null states for text fields. ISNULL() should be avoided for text fields as it misses empty strings."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s3-obj2",
                    title: "Given a scenario, determine the capabilities and use cases for approval processes.",
                    topics: [
                        StudyTopic(id: "ab-s14-t1", number: 1, question: "What are entry criteria in an approval process and what happens if a record does not meet them when submitted?", answer: "Entry criteria define the conditions a record must meet to enter the approval process (e.g., Discount > 20%). If a record is submitted but does not meet the entry criteria, the process is automatically approved (or skipped) based on the 'If the submitter's profile does not have authority' setting, or it moves to the next step. By default, records not meeting criteria are auto-approved."),
                        StudyTopic(id: "ab-s14-t2", number: 2, question: "What types of approvers can be defined in an approval process step (user, related user, manager field, queue)?", answer: "Approver types in a step: (1) Specific user(s) — named individuals, (2) Related user — a user referenced by a field on the record (e.g., the record's Account Manager), (3) Manager field — the submitting user's manager from the user hierarchy, (4) Queue — any member of a specified queue can approve. Multiple approver types can be combined in a single step."),
                        StudyTopic(id: "ab-s14-t3", number: 3, question: "What is an initial submission action in an approval process and when does it execute?", answer: "The initial submission action executes immediately when a user submits the record for approval — before any approver reviews it. Common uses: lock the record to prevent editing, update a Status field to 'Pending Approval', send a notification to the submitter confirming receipt. It runs regardless of whether the record is eventually approved or rejected."),
                        StudyTopic(id: "ab-s14-t4", number: 4, question: "What is a final approval action in an approval process and when does it execute?", answer: "The final approval action executes when the record has been approved by all required approvers and the process is complete. Common uses: update a Status field to 'Approved', unlock the record, send a congratulations notification, trigger downstream automation. It runs only after the last approval step is approved."),
                        StudyTopic(id: "ab-s14-t5", number: 5, question: "What is a final rejection action in an approval process and when does it execute?", answer: "The final rejection action executes when any approver rejects the record and the rejection is final (no further steps). Common uses: unlock the record, update Status to 'Rejected', send a notification to the submitter explaining rejection. If the process has multiple steps with different rejection behaviors, the final rejection action runs after the rejection cascade completes."),
                        StudyTopic(id: "ab-s14-t6", number: 6, question: "What is a recall action in an approval process?", answer: "A recall action executes when the submitter (or an admin) recalls (withdraws) a pending approval request. Common uses: unlock the record, update Status back to its pre-submission value (e.g., 'Draft'), notify the approver that the request has been withdrawn. Recall removes the pending approval from the approver's queue."),
                        StudyTopic(id: "ab-s14-t7", number: 7, question: "What does record locking mean in an approval process and which types of users can still edit a locked record?", answer: "Record locking prevents regular users from editing a record while it is pending approval. Only: (1) administrators, (2) the current approver in the step, and (3) users with 'Modify All' on the object can edit a locked record. Locking is typically configured as an initial submission action. It ensures the record is not changed while under review."),
                        StudyTopic(id: "ab-s14-t8", number: 8, question: "What is a delegated approver in an approval process?", answer: "A delegated approver is an alternate user designated to approve on behalf of a primary approver when that approver is unavailable (e.g., on vacation). Each user can set a delegated approver in their user settings. When configured in the approval process to 'Allow delegation', the delegated approver receives approval tasks in addition to the primary approver."),
                        StudyTopic(id: "ab-s14-t9", number: 9, question: "What is the maximum number of steps allowed in a single approval process?", answer: "A single approval process can have up to 30 steps. Each step can have different approvers, criteria, and actions. In practice, most approval processes have far fewer steps (typically 1-5). The 30-step limit is sufficient for even complex multi-tier approval hierarchies."),
                        StudyTopic(id: "ab-s14-t10", number: 10, question: "What is the difference between 'Approve or reject based on the first response' and 'Require unanimous approval from all selected approvers' in a multi-approver step?", answer: "'First response' means whichever assigned approver acts first determines the outcome — if one approves, it is approved; if one rejects, it is rejected. 'Unanimous' means ALL assigned approvers must approve for the step to advance; a single rejection rejects the entire step. Use first-response for speed; use unanimous for consensus-required decisions."),
                        StudyTopic(id: "ab-s14-t11", number: 11, question: "What types of automated actions can be configured as approval, rejection, recall, or initial submission actions?", answer: "Supported action types in approval processes: Field Update (change a field value), Email Alert (send a templated email), Task (create a follow-up task), and Outbound Message (send a SOAP message to an external endpoint). Flows can also be triggered from approval process actions via the 'Launch a Flow' action type."),
                        StudyTopic(id: "ab-s14-t12", number: 12, question: "A manager must approve any discount greater than 20% before an opportunity can advance to 'Negotiation/Review'. Which Salesforce feature best models this requirement?", answer: "An Approval Process on the Opportunity object. Configure: entry criteria = Discount__c > 20%, approver = the submitting user's manager (manager field), initial submission action = lock the record, final approval action = update Stage to 'Negotiation/Review'. This precisely matches the business requirement with native Salesforce declarative tools."),
                        StudyTopic(id: "ab-s14-t13", number: 13, question: "Can an approval process be triggered programmatically from a Flow?", answer: "Yes. A Flow can submit a record for approval using the 'Submit for Approval' core action in Flow Builder. This allows automated submission based on trigger conditions without user action. For example, a record-triggered Flow could automatically submit an Opportunity for approval when Discount is set above a threshold."),
                        StudyTopic(id: "ab-s14-t14", number: 14, question: "What is an approval page layout and what fields does it display to the approver?", answer: "The approval page layout defines which fields the approver sees on the approval detail page when reviewing a request. It is separate from the record's page layout. Admins configure it to show only the fields relevant to the approval decision (e.g., Discount %, Opportunity Name, Amount). A well-designed approval page layout gives approvers focused context without information overload."),
                        StudyTopic(id: "ab-s14-t15", number: 15, question: "A business requires that when an approval request is rejected, the record is unlocked and a field is updated to 'Rejected'. Select two approval process action types that must be configured to achieve this outcome.", answer: "Two actions needed: (1) Field Update action — set the Status (or Approval_Status__c) field to 'Rejected'. (2) Field Update action — set the record lock: use an 'Unlock the record for editing' field update, OR configure the rejection action to unlock. Both actions are configured in the 'Final Rejection Actions' section of the approval process. These two together satisfy both requirements."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s3-obj3",
                    title: "Given a scenario, determine the tool or action needed to meet business requirements.",
                    topics: [
                        StudyTopic(id: "ab-s15-t1", number: 1, question: "What are the four action types that Workflow Rules support (field updates, email alerts, tasks, outbound messages)?", answer: "Workflow Rules support exactly four action types: (1) Field Update — change a field value on the record or its master, (2) Email Alert — send a templated email to specified recipients, (3) Task — create a follow-up task and assign it, (4) Outbound Message — send a SOAP XML notification to an external endpoint. No other action types are supported. Workflow Rules are considered legacy — Flow is the recommended replacement."),
                        StudyTopic(id: "ab-s15-t2", number: 2, question: "Can Workflow Rules create new records?", answer: "No. Workflow Rules cannot create new records. They can only update the triggering record or its master (via field update), send emails, create tasks, or send outbound messages. To create new related records declaratively, use a record-triggered Flow with a Create Records element."),
                        StudyTopic(id: "ab-s15-t3", number: 3, question: "What is the current Salesforce recommendation for new automation — Workflow Rules, Process Builder, or Flow Builder?", answer: "Salesforce recommends Flow Builder for all new automation. Workflow Rules and Process Builder are retired (or being retired) — Salesforce announced the end-of-life for both. Existing Workflow Rules continue to function, but new automation should be built in Flow Builder, which supersedes both with greater capability and maintainability."),
                        StudyTopic(id: "ab-s15-t4", number: 4, question: "What is a record-triggered Flow and what record events can trigger it?", answer: "A record-triggered Flow executes automatically when a record is created, updated, or deleted. Trigger options: (1) A record is created, (2) A record is updated, (3) A record is created or updated, (4) A record is deleted. You can further refine with entry conditions so the Flow only runs when specific field criteria are met — preventing unnecessary executions."),
                        StudyTopic(id: "ab-s15-t5", number: 5, question: "What is the difference between a before-save and an after-save record-triggered Flow?", answer: "Before-save Flow: runs before the record is committed to the database. Can update fields on the triggering record without a DML operation (fast). Cannot create/update/delete other records. After-save Flow: runs after the record is committed. Can create, update, or delete other records. Uses DML operations. Before-save is more efficient for field updates on the triggering record."),
                        StudyTopic(id: "ab-s15-t6", number: 6, question: "When is a before-save record-triggered Flow preferred over an after-save Flow?", answer: "Before-save is preferred when you only need to set/update fields on the triggering record itself — it does not consume a DML operation, making it faster and more governor-limit-friendly. Use before-save for: setting values, calculating derived fields, formatting text on save. Use after-save when you need to interact with other records (create child records, update related objects)."),
                        StudyTopic(id: "ab-s15-t7", number: 7, question: "What is a scheduled-triggered (Scheduled Path) Flow and when would you use one?", answer: "A Scheduled Path (on a record-triggered Flow) runs at a specified time relative to a date/time field on the record (e.g., '30 days after CloseDate'). Use it for: sending follow-up reminders, escalating cases after SLA breach, automatically advancing records after a time delay. The record must still meet entry criteria at the time the scheduled path fires."),
                        StudyTopic(id: "ab-s15-t8", number: 8, question: "What is a Screen Flow and how is it surfaced to users in a Lightning app?", answer: "A Screen Flow is an interactive, guided wizard-style Flow that displays UI screens to collect input from users. It is surfaced via: a Lightning component on a record page (Flow component in App Builder), a Quick Action, a Utility Bar component, a custom Tab, or embedded in an Experience Cloud page. Users interact with the screens and the Flow processes their input."),
                        StudyTopic(id: "ab-s15-t9", number: 9, question: "What is an auto-launched Flow and when would it be used instead of a Screen Flow?", answer: "An auto-launched Flow runs without any user interaction — no screens. It is triggered by: record events (record-triggered Flow), Apex code, a process, another Flow (subflow), a REST API call, or a schedule. Use auto-launched Flows for background automation that does not need user input. Screen Flows are only for user-interactive guided processes."),
                        StudyTopic(id: "ab-s15-t10", number: 10, question: "What is a Platform Event-triggered Flow and what is its primary use case?", answer: "A Platform Event-triggered Flow fires when a specific Platform Event message is published. Primary use case: real-time integrations where an external system or Apex publishes a Platform Event and the Flow handles the resulting business logic (e.g., create a record, send a notification). It decouples the publishing system from the business logic handler."),
                        StudyTopic(id: "ab-s15-t11", number: 11, question: "A business needs to automatically create a follow-up Task 30 days after an Opportunity closes. Which automation tool and feature should be used?", answer: "Use a record-triggered Flow on Opportunity with a Scheduled Path set to '30 days after CloseDate'. When the CloseDate is reached (with the record in a Closed stage), the scheduled path fires a Create Records element to create a Task. This is the declarative, modern replacement for time-based workflow actions."),
                        StudyTopic(id: "ab-s15-t12", number: 12, question: "What does an outbound message (Workflow) do vs. an HTTP callout action in a Flow?", answer: "Outbound Message: sends a one-way SOAP/XML notification to an external endpoint — no response is processed back into Salesforce. HTTP Callout action (Flow): sends an HTTP request to a REST or SOAP endpoint and can process the response back into the Flow to update Salesforce records. HTTP Callout is bidirectional; Outbound Message is one-way notification only."),
                        StudyTopic(id: "ab-s15-t13", number: 13, question: "A business requirement is to update a related Account field whenever a related Opportunity Stage changes. Legacy Workflow Rules are already in use. Which tool handles this?", answer: "A record-triggered Flow on Opportunity (triggered on update, entry condition: Stage changed) with an Update Records element targeting the related Account. Flow Builder handles cross-object field updates natively and is the recommended modern tool. Legacy Workflow Rules can also do this via a Field Update on the master (Account), but Flow is the preferred path."),
                        StudyTopic(id: "ab-s15-t14", number: 14, question: "A company needs to send a one-way SOAP notification to an external system when a record status changes and does not need a response. Which automation feature handles this?", answer: "An Outbound Message (configured in a Workflow Rule or Approval Process action). It sends a SOAP XML message to an external endpoint and does not wait for or process a response back into Salesforce. If using Flow, an HTTP Callout to a SOAP endpoint also works but is bidirectional. For purely one-way SOAP notification, Outbound Message is the native feature."),
                        StudyTopic(id: "ab-s15-t15", number: 15, question: "A business needs to (1) create a follow-up task when a case is closed AND (2) post a Chatter message to the case record. Select two automation actions that together satisfy both requirements using a single record-triggered Flow.", answer: "Two actions in a single after-save record-triggered Flow: (1) Create Records element — create a Task related to the Case. (2) Post to Chatter core action (or Create a FeedItem record) — post a message to the Case's Chatter feed. Both actions can be sequential elements in one Flow, fired when Case Status = 'Closed'. No need for two separate automation tools."),
                        StudyTopic(id: "ab-s15-t16", number: 16, question: "What does the Get Records element in Flow Builder do and how does it query Salesforce data?", answer: "The Get Records element queries Salesforce using filter conditions you define (like a SOQL WHERE clause) and returns matching records. You specify the object, filter criteria, sort order, and how many records to retrieve. The results are stored in a record variable (single record) or record collection variable (multiple records) for use in subsequent Flow elements."),
                        StudyTopic(id: "ab-s15-t17", number: 17, question: "What are the two output modes of the Get Records element in Flow Builder (single record vs. record collection), and when would you choose each?", answer: "Single record: returns only the first matching record — use when you know only one record matches or only need one (e.g., get the Account related to the triggering Contact). Record collection: returns all matching records as a list — use when you need to process multiple records (e.g., get all open Cases related to an Account for loop processing)."),
                        StudyTopic(id: "ab-s15-t18", number: 18, question: "What does the Delete Records element in Flow Builder do, and what happens to child records in a master-detail relationship when the parent is deleted via Flow?", answer: "The Delete Records element permanently deletes specified records (moves them to Recycle Bin). If the deleted record is a master in a master-detail relationship, child records are cascade deleted — exactly as if deleted from the UI. The Flow does not need to explicitly delete child records; the platform handles cascade deletion automatically."),
                        StudyTopic(id: "ab-s15-t19", number: 19, question: "What does the Create Records element in Flow Builder do, and can it create multiple records in a single element using a record collection variable?", answer: "The Create Records element inserts one or more new records into Salesforce. Yes — you can use a record collection variable as the input, allowing the element to create multiple records in a single bulk operation. This is important for governor limit efficiency: creating 100 records from a collection in one element is far better than looping with individual Create elements."),
                        StudyTopic(id: "ab-s15-t20", number: 20, question: "What does the Update Records element in Flow Builder do, and how does it differ from updating the triggering record via a fast field update assignment in a before-save Flow?", answer: "Update Records element: uses a DML update operation to modify records (can update any records, including unrelated ones). Costs a DML governor limit count. Fast field update in a before-save Flow: directly modifies fields on the triggering record in memory before the record is saved — no DML operation, no governor limit consumption. Before-save fast updates are more efficient for simple field updates on the triggering record."),
                        StudyTopic(id: "ab-s15-t21", number: 21, question: "What is a collection variable in Flow Builder and when is it used with a Loop element?", answer: "A collection variable stores multiple records (or values) of the same type — like an array. It is used with a Loop element to iterate over each item in the collection one at a time. Common pattern: Get Records returns a collection, a Loop iterates over each record, a Decision evaluates each one, and an Assignment adds qualifying records to a new collection for bulk Update/Create."),
                        StudyTopic(id: "ab-s15-t22", number: 22, question: "What is the Decision element in Flow Builder, how does it create branching logic, and what is the 'Default Outcome'?", answer: "The Decision element evaluates one or more conditions and routes Flow execution down different paths (outcomes) based on which condition is true. Each outcome has its own set of conditions. The 'Default Outcome' is the path taken when no other outcome's conditions are met — always include a default to prevent unhandled scenarios and Flow errors."),
                        StudyTopic(id: "ab-s15-t23", number: 23, question: "How is a collection variable populated using an Assignment element within a Flow loop?", answer: "Inside a Loop, use an Assignment element to add the current loop item to a collection variable using the 'Add' operator: Assignment sets [CollectionVariable] = [CollectionVariable] + {Loop_Current_Item}. This appends each qualifying item to the collection as the loop progresses. After the loop exits, the collection variable contains all the accumulated items for bulk processing."),
                        StudyTopic(id: "ab-s15-t24", number: 24, question: "What is the Assignment element in Flow Builder and what types of operators can it apply to a variable (equals, add, subtract, remove, add at start, remove all)?", answer: "The Assignment element sets or modifies variable values. Operators: Equals (set the variable to a value), Add (add to a number or append to a collection), Subtract (subtract from a number), Remove (remove a specific value from a collection), Add at Start (prepend to a collection), Remove All (clear all items from a collection matching a value). Multiple assignments can be stacked in a single element."),
                        StudyTopic(id: "ab-s15-t25", number: 25, question: "What is the Loop element in Flow Builder, what data type does it iterate over, and what are the two connectors that exit the loop (For Each Item and After Last Item)?", answer: "The Loop element iterates over a collection variable (list of records or primitive values). Two exit connectors: (1) 'For Each Item' — executes once per item in the collection (the loop body), (2) 'After Last Item' — executes once after all items have been processed (post-loop logic). Everything inside the loop body runs for each collection item."),
                        StudyTopic(id: "ab-s15-t26", number: 26, question: "What running context options are available for a record-triggered Flow (System Mode Without Sharing, System Mode With Sharing, Running User)?", answer: "Context options: (1) System Mode Without Sharing — runs with elevated access, ignores sharing rules and OWD (sees all records). (2) System Mode With Sharing — runs elevated but respects sharing rules. (3) User or System Mode Default — inherits the context of the triggering user. The choice affects which records the Flow can query and update, with security implications."),
                        StudyTopic(id: "ab-s15-t27", number: 27, question: "What is the Pause element in a Screen Flow and how does it allow the flow interview to be suspended and later resumed?", answer: "The Pause element suspends a Screen Flow interview and saves its state. The user can close the browser and return later to resume from the paused point. Paused interviews are accessible via the 'Paused Interviews' component. This is useful for long multi-step processes (e.g., a complex onboarding wizard that users complete over multiple sessions). It requires the Flow to be launched in Lightning Experience or Experience Cloud."),
                        StudyTopic(id: "ab-s15-t28", number: 28, question: "What is the difference between using an Email Alert core action and a Send Email core action in a Flow?", answer: "Email Alert core action: uses a pre-configured Email Alert (with a template, recipients, and from address set up in Setup). Reusable across automation tools. Send Email core action: sends an email directly from the Flow with dynamic recipients, subject, and body — more flexible but requires configuring each detail in the Flow itself. Email Alert is better for standardized, reusable notifications; Send Email for dynamic, context-specific messages."),
                        StudyTopic(id: "ab-s15-t29", number: 29, question: "What is a custom notification action in Flow Builder and how is the notification delivered to recipients?", answer: "The 'Send Custom Notification' core action in Flow sends a bell notification (in-app) to specified users through the Salesforce Notification Builder framework. Recipients receive it as a bell icon notification in the app and optionally as a push notification on mobile. You must first create a Custom Notification Type in Setup, then reference it in the Flow action."),
                        StudyTopic(id: "ab-s15-t30", number: 30, question: "What is a scheduled path in a record-triggered Flow and how is its delay defined relative to a date/time field value on the triggering record?", answer: "A scheduled path is a time-delayed branch of a record-triggered Flow. The delay is defined as: X Minutes/Hours/Days/Months Before or After a specified Date or Date/Time field on the record (e.g., '3 days before Close Date'). At the defined time, Salesforce re-evaluates whether the record still meets the entry criteria and executes the scheduled path if so."),
                        StudyTopic(id: "ab-s15-t31", number: 31, question: "A Flow must retrieve all open cases related to an account, evaluate each one, and update those older than 30 days. Select two Flow elements required to implement this logic.", answer: "Two required elements: (1) Get Records — query all open Cases related to the Account (filter: AccountId = Account, Status != Closed) and store as a record collection. (2) Loop — iterate over the collection to evaluate each Case's CreatedDate. Inside the loop, a Decision element checks age > 30 days, and an Assignment builds a collection of qualifying Cases for a bulk Update Records after the loop."),
                        StudyTopic(id: "ab-s15-t32", number: 32, question: "Can a record-triggered Flow be configured to fire on record deletion, and what record event trigger option enables this?", answer: "Yes. Set the trigger to 'A record is deleted'. The Flow fires before the record is deleted (before-delete context). This allows you to read the record's field values, create related records, log history, or send notifications based on the deletion event. Note: you cannot update the triggering record in a delete-triggered Flow since it is being deleted."),
                        StudyTopic(id: "ab-s15-t33", number: 33, question: "What is a custom label in Salesforce, where is it used, and why is it preferred over hardcoding text values in Flows, Apex, or Visualforce pages?", answer: "A custom label is a configurable text value stored in Salesforce metadata, accessible by name in Flows, Apex ({!$Label.Label_Name}), and Visualforce pages. Preferred over hardcoding because: (1) easily changed in one place without modifying code/Flow, (2) supports translation into multiple languages (custom labels are the foundation of Salesforce's translation framework), (3) deployable via change sets."),
                        StudyTopic(id: "ab-s15-t34", number: 34, question: "What is the difference between 'System Mode Without Sharing' and 'System Mode With Sharing' as running contexts in a record-triggered Flow?", answer: "Without Sharing: the Flow ignores the org's sharing model — it can read and write any record regardless of OWD, sharing rules, or who owns the record. With Sharing: the Flow respects the org's sharing rules when querying and updating records, but still runs as a system user (not the triggering user's permissions). Without Sharing is riskier but sometimes necessary for automation that must touch records the triggering user can't see."),
                        StudyTopic(id: "ab-s15-t35", number: 35, question: "What is the 'Run Flow' action in an approval process and what type of Flow can be launched from an approval action?", answer: "The 'Run Flow' action in an approval process launches an auto-launched (non-screen) Flow as part of an approval, rejection, recall, or submission action. The Flow must be of type 'Auto-launched Flow' — Screen Flows cannot be used in approval process actions. This allows complex logic (multi-record creates, external callouts) to be triggered as part of the approval lifecycle."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s3-obj4",
                    title: "Given a set of business requirements, recommend a solution to automate business processes while avoiding errors in automation.",
                    topics: [
                        StudyTopic(id: "ab-s16-t1", number: 1, question: "What is the Salesforce order of execution when a record is saved, and why is it important for automation design?", answer: "Key order: (1) Before-save validation rules and before-save Flows, (2) Apex before triggers, (3) Duplicate rules, (4) Record saved to database (but not committed), (5) Apex after triggers, (6) After-save Flows, (7) Workflow rules, (8) Process Builder processes, (9) Commit. Understanding this prevents conflicts — e.g., a before-save Flow updating a field that an Apex before trigger also updates could cause unexpected overwrites."),
                        StudyTopic(id: "ab-s16-t2", number: 2, question: "What is 'bulkification' in the context of record-triggered Flows and why does it matter?", answer: "Bulkification means the platform batches record operations together and processes them in bulk rather than one-by-one. Record-triggered Flows are bulkified — when 200 records are updated at once (e.g., via Data Loader), the Flow runs once per batch, not 200 individual times. This prevents hitting governor limits. Poorly designed Flows with DML inside loops break bulkification and can cause limit errors."),
                        StudyTopic(id: "ab-s16-t3", number: 3, question: "What is a circular automation loop and how can it occur between Flows and other automation tools?", answer: "A circular loop occurs when automation A triggers automation B, which triggers automation A again, creating infinite recursion. Example: a Flow updates Account when Opportunity is saved, and another Flow updates Opportunity when Account is saved — each triggers the other infinitely. Prevented by: entry conditions (check if the triggering field actually changed), version-aware design, and setting 'Run Once Per Record' where appropriate."),
                        StudyTopic(id: "ab-s16-t4", number: 4, question: "What happens when a Flow encounters an unhandled fault (error) during execution?", answer: "An unhandled fault causes the Flow to stop and roll back any changes made in that transaction. An error email is sent to the Flow admin (the user who last modified the Flow). From the user's perspective, the record save fails with a generic error message. All DML operations in the transaction are rolled back. A fault path should be configured to handle errors gracefully."),
                        StudyTopic(id: "ab-s16-t5", number: 5, question: "What is a fault path in Flow Builder and how should it be configured to handle errors gracefully?", answer: "A fault path is an alternative connector on Flow elements that is followed when an error occurs. Best practice: connect the fault path to a Screen (for Screen Flows) displaying a user-friendly error message, or to a Create Records element that logs the error details to a custom log object, or to a Send Email action alerting an admin. Without a fault path, errors are unhandled and cause full transaction rollback."),
                        StudyTopic(id: "ab-s16-t6", number: 6, question: "What is a fast field update (before-save) in a Flow and how does it differ from a DML operation in terms of governor limit consumption?", answer: "A fast field update in a before-save Flow directly modifies the triggering record's fields in memory — it does not execute a separate DML statement. This means it does not count against the DML statements governor limit (150 per transaction). A DML operation in an after-save Flow (via Update Records) does count. Before-save fast updates are significantly more efficient for simple field manipulations."),
                        StudyTopic(id: "ab-s16-t7", number: 7, question: "When should you use a subflow to modularize complex automation logic?", answer: "Use a subflow when: the same logic is needed in multiple Flows (DRY principle), a Flow becomes too large to maintain easily, you want to separate concerns (e.g., notification logic vs. data update logic), or when testing individual logic blocks independently is desirable. A subflow is a reusable auto-launched Flow called from a parent Flow using the Subflow element."),
                        StudyTopic(id: "ab-s16-t8", number: 8, question: "A company has multiple active record-triggered Flows on the same object. What risk must be managed to prevent runaway automation?", answer: "The risk is interaction and ordering conflicts between Flows — and potentially circular loops. Manage by: (1) using specific entry conditions on each Flow so they only fire when truly needed, (2) ensuring no two Flows update the same field in conflicting ways, (3) using a single 'orchestrator' Flow where possible rather than many small Flows, and (4) testing with bulk data to check for governor limit issues."),
                        StudyTopic(id: "ab-s16-t9", number: 9, question: "A before-save Flow needs to update several fields on a record. An after-save Flow on the same object sends an email. What is the correct execution order?", answer: "The before-save Flow executes first — it runs before the record is committed. The after-save Flow executes second — after the record is committed to the database. So the order is: before-save Flow field updates → record saved → after-save Flow email. The after-save Flow will see the field values set by the before-save Flow since those updates are committed first."),
                        StudyTopic(id: "ab-s16-t10", number: 10, question: "A company is migrating from legacy Workflow Rules to Flow Builder. Select two true statements about Workflow Rules that describe what Flow Builder supersedes.", answer: "Two true statements: (1) Workflow Rules cannot create new records — Flow Builder can. (2) Workflow Rules support only four action types (Field Update, Email Alert, Task, Outbound Message) — Flow Builder supports all of these plus many more (HTTP callouts, custom notifications, Apex actions, subflows, etc.). Flow Builder is a strict superset of Workflow Rule capabilities."),
                        StudyTopic(id: "ab-s16-t11", number: 11, question: "What happens to the previously active Flow version when a new version is activated?", answer: "When a new version of a Flow is activated, the previously active version automatically changes status to 'Obsolete'. It no longer runs for new triggers. Any in-progress (paused) interviews on the old version continue to run on that version until they complete. Only one version of a Flow can be Active at any time."),
                        StudyTopic(id: "ab-s16-t12", number: 12, question: "How do you debug a Flow using the Debug button in Flow Builder, and what information does a debug run provide to help identify errors?", answer: "In Flow Builder, click the Debug button to open the Debug panel. You specify input variable values and run the Flow in a simulated context. The debug log shows: each element that executed, the values of variables at each step, which path was taken at each Decision, and any errors with detailed messages. This allows identification of logic errors and unexpected variable values without deploying to users."),
                        StudyTopic(id: "ab-s16-t13", number: 13, question: "A record-triggered Flow must update a Status field only when the record transitions from 'Draft' to 'In Review', not on every save. Which Flow configuration prevents it from running on unrelated saves?", answer: "Configure entry conditions using the $Record and $Record__Prior global variables. Set the trigger to 'A record is updated' and add an entry condition: {!$Record.Status__c} = 'In Review' AND {!$Record__Prior.Status__c} = 'Draft'. This ensures the Flow only executes when the Status field specifically transitions from Draft to In Review, not on any other save."),
                        StudyTopic(id: "ab-s16-t14", number: 14, question: "What is the difference between the $Record and $Record__Prior global variables in a record-triggered Flow, and how are they used to detect whether a specific field was changed?", answer: "$Record: contains the current (new) values of the triggering record after the change. $Record__Prior: contains the previous values before the current save (only available on update triggers). To detect a field change, compare: {!$Record.Field__c} != {!$Record__Prior.Field__c}. If they differ, the field was changed in this save. This is the declarative equivalent of 'old vs. new' in Apex triggers."),
                        StudyTopic(id: "ab-s16-t15", number: 15, question: "How do entry conditions on a record-triggered Flow prevent unnecessary executions and help avoid recursive loops?", answer: "Entry conditions act as a gate — the Flow only executes if the record meets the specified conditions at trigger time. For example, 'only run if Status changed from Draft to Active.' This prevents the Flow from firing on every save, reducing governor limit consumption, preventing unintended side effects, and breaking potential recursive loops where the Flow's own updates would re-trigger it."),
                        StudyTopic(id: "ab-s16-t16", number: 16, question: "When a before-save record-triggered Flow and an after-save record-triggered Flow both exist on the same object, what is the execution order relative to each other and relative to Apex triggers?", answer: "Order: (1) Before-save Flows run, (2) Apex before triggers run, (3) Record is saved to DB (not committed), (4) Apex after triggers run, (5) After-save Flows run, (6) Transaction commits. Before-save Flows run before Apex before triggers. After-save Flows run after Apex after triggers. This ordering is critical when both automation types modify the same fields."),
                        StudyTopic(id: "ab-s16-t17", number: 17, question: "What are time-based workflow actions, and how do scheduled paths in a record-triggered Flow provide a more modern equivalent?", answer: "Time-based workflow actions are Workflow Rule actions that fire at a future time relative to a date field (e.g., 'send reminder 7 days before due date'). Scheduled paths in a record-triggered Flow provide the same capability with much greater flexibility: you can perform any Flow action (not just 4 types), use more complex conditions, and chain scheduled paths. Scheduled paths are the modern, recommended replacement."),
                        StudyTopic(id: "ab-s16-t18", number: 18, question: "What are the three version statuses a Flow can have (Draft, Active, Obsolete)?", answer: "Draft: the Flow is being built or edited — it is not running for any users. Active: the Flow is live and executes for triggers/users. Only one version can be Active at a time. Obsolete: a previously active version that was deactivated when a new version was activated. Obsolete versions continue processing any paused interviews but do not accept new executions."),
                        StudyTopic(id: "ab-s16-t19", number: 19, question: "What is the 'Run Once Per Record' option in a record-triggered Flow and when should it be enabled?", answer: "'Run Once Per Record' (also called 'Run Only When Record Is Created' or the 'Runs Once Per Record' entry condition) ensures the Flow only fires the first time a record matches the entry conditions in its lifetime — not on subsequent saves that re-match. Enable it when the Flow should only set up initial values or send a one-time welcome notification upon first meeting the criteria, not every time the record is saved."),
                    ]
                )
            ]
        ),

        // Section 4: User Interface (53 topics)
        StudySection(
            id: "ab-s4",
            title: "User Interface",
            color: Color(red: 0.55, green: 0.30, blue: 0.60),
            lightColor: Color(red: 0.95, green: 0.92, blue: 0.97),
            icon: "macwindow",
            objectives: [
                StudyObjective(
                    id: "ab-s4-obj1",
                    title: "Describe the user interface customization options.",
                    topics: [
                        StudyTopic(id: "ab-s17-t1", number: 1, question: "What is the difference between a Lightning App Page, a Record Page, and a Home Page in Lightning App Builder?", answer: "App Page: a standalone page accessible via a tab in a Lightning app — used for dashboards, embedded reports, or custom landing pages. Record Page: customizes what users see when opening a specific object's record — fields, related lists, components. Home Page: customizes the main 'Home' screen for an app or the org's default home — typically shows news, recent items, dashboard components. Each page type has different component options."),
                        StudyTopic(id: "ab-s17-t2", number: 2, question: "What is Lightning App Builder and what types of pages can be customized with it?", answer: "Lightning App Builder is a declarative drag-and-drop tool for building Lightning pages. Page types: Record Pages (object detail pages), App Pages (standalone app pages), Home Pages (the home tab), and Email Application Panes (for Outlook/Gmail integrations). You can place standard and custom Lightning components, set component visibility, and assign pages to specific apps, profiles, and record types."),
                        StudyTopic(id: "ab-s17-t3", number: 3, question: "What is Dynamic Forms in Lightning App Builder and which objects does it support?", answer: "Dynamic Forms moves field sections from the page layout directly into the Lightning App Builder canvas, enabling component-level visibility rules on individual fields and sections. Initially only supported custom objects; Salesforce has been progressively rolling it out to standard objects (e.g., Account, Contact, Opportunity in recent releases). Check current release notes for the latest supported objects."),
                        StudyTopic(id: "ab-s17-t4", number: 4, question: "What is the advantage of Dynamic Forms over traditional page layout field sections for controlling field visibility?", answer: "Traditional page layouts require different layouts per profile/record type to show different fields. Dynamic Forms allows visibility rules directly on individual fields or sections — a field can be shown only when a specific picklist value is selected, a checkbox is checked, or a user has a specific permission. This eliminates the need for multiple layouts for the same object/record type combination."),
                        StudyTopic(id: "ab-s17-t5", number: 5, question: "What is the key eligibility restriction for Dynamic Forms (custom objects in Lightning Experience only, not standard objects initially)?", answer: "Dynamic Forms was initially only available for custom objects in Lightning Experience — not supported in Classic or for standard objects at launch. Salesforce has progressively expanded support to more standard objects with each release. The exam typically tests the original constraint: Dynamic Forms is a Lightning Experience-only feature and was not available for all standard objects from the start."),
                        StudyTopic(id: "ab-s17-t6", number: 6, question: "What is a record type and how does it interact with page layouts in Lightning Experience?", answer: "A record type determines which page layout a user sees on a record (via the profile-to-record-type-to-layout mapping). In Lightning Experience, record types also determine which picklist values are available and which business process applies. The profile specifies: for this object, users with this profile see page layout X when the record has record type Y."),
                        StudyTopic(id: "ab-s17-t7", number: 7, question: "How are page layouts assigned to users in Salesforce?", answer: "Page layouts are assigned through the Profile (or Permission Set in newer orgs). In Setup > Object Manager > Object > Page Layout Assignment, you define the matrix: for each Profile + Record Type combination, which layout is displayed. A user's combination of profile and record type determines their layout. If no specific assignment exists, the object's default layout is used."),
                        StudyTopic(id: "ab-s17-t8", number: 8, question: "What is a compact layout and where is it displayed in Salesforce (record highlights panel, mobile app, Chatter)?", answer: "A compact layout specifies the top fields to display in: (1) the record highlights panel at the top of a Lightning record page, (2) record cards in related lists and list views, (3) the Salesforce mobile app record card header, and (4) Chatter post previews when a record is @mentioned. It is not the full page layout — it shows only the most critical identifying fields (up to 10, but typically 4-7 are shown)."),
                        StudyTopic(id: "ab-s17-t9", number: 9, question: "What is a list view and what customization options does it support?", answer: "A list view is a filtered, column-configured view of object records. Customization options: filter criteria (field conditions), columns displayed (select which fields appear), sort order, Kanban view toggle, and sharing (private, visible to specific groups, or public). Admins can create shared list views; users can create personal ones. List views also support inline editing of records."),
                        StudyTopic(id: "ab-s17-t10", number: 10, question: "What is a Lightning App and how does it differ from a Classic App in terms of navigation and component support?", answer: "A Lightning App offers: tab-based or console navigation, a utility bar, support for Lightning components and custom pages, mobile-responsive design, and custom themes. A Classic App is a simple collection of tabs with a custom logo — no utility bar, no console navigation, no Lightning component support. Lightning Apps are configured in Setup > App Manager."),
                        StudyTopic(id: "ab-s17-t11", number: 11, question: "What are component visibility filters in Lightning App Builder and how are they configured?", answer: "Component visibility filters are rules that determine whether a Lightning component is shown or hidden on a record page based on conditions. Conditions can evaluate: record field values (e.g., show only when Status = Active), user profile or permission, device form factor (desktop vs. mobile), and record type. They are configured by selecting a component in App Builder and clicking the 'Set Component Visibility' option."),
                        StudyTopic(id: "ab-s17-t12", number: 12, question: "A company wants certain Lightning components to be visible only to users with the 'Sales Manager' permission set. Which App Builder feature enables this?", answer: "Component Visibility Filters in Lightning App Builder. Add a visibility filter condition: 'User > Permission > Has Permission Set: Sales Manager' (or equivalent permission-based condition). The component is rendered only when the logged-in user has the Sales Manager permission set assigned. This does not require creating a separate page per user group."),
                        StudyTopic(id: "ab-s17-t13", number: 13, question: "How are Lightning pages assigned to users — by app, record type, and/or profile?", answer: "Lightning pages can be assigned at three levels: (1) Default for all — applies to everyone unless overridden. (2) App default — applies when accessed from a specific Lightning app. (3) App, Record Type, and Profile — the most specific level, allowing different record pages for different combinations of app + record type + profile. The most specific assignment wins."),
                        StudyTopic(id: "ab-s17-t14", number: 14, question: "A company wants to show different fields on an Opportunity record page based on record type without creating multiple page layouts. Select two Lightning App Builder features that together enable field-level visibility control by record type.", answer: "Two features: (1) Dynamic Forms — moves fields out of the page layout and onto the App Builder canvas as individual field components. (2) Component Visibility Filters — set a filter on each field component so it is visible only when the record's record type equals a specific value. Together, one record page with Dynamic Forms + visibility filters replaces multiple record type-specific layouts."),
                        StudyTopic(id: "ab-s17-t15", number: 15, question: "What are the types of custom tabs available in Salesforce (Object Tab, Web Tab, Visualforce Tab, Lightning Component Tab) and when would you use each?", answer: "Object Tab: displays list/detail views of a standard or custom object. Web Tab: opens an external URL in the Salesforce window — good for embedding external web apps. Visualforce Tab: hosts a Visualforce page as a tab. Lightning Component Tab: hosts a Lightning App Page or an Aura/LWC component as a standalone tab. Choose based on whether you're surfacing object data, an external site, a VF page, or a custom Lightning page."),
                        StudyTopic(id: "ab-s17-t16", number: 16, question: "How does tab visibility on a profile or permission set affect what appears in the navigation bar, and what is the difference between Default On, Default Off, and Tab Hidden?", answer: "Default On: the tab appears in the navigation bar for users on this profile unless they personally remove it. Default Off: the tab does NOT appear by default, but users can add it via their personalization settings. Tab Hidden: the tab is completely invisible — users cannot add it. Note: Tab Hidden does not restrict record access — users can still access records via URL or related lists."),
                        StudyTopic(id: "ab-s17-t17", number: 17, question: "What is the Kanban view in Salesforce, which objects support it, and how is it organized?", answer: "Kanban view displays records as cards organized in columns based on a picklist field value. It is available on objects with picklist fields when using list views in Lightning Experience. Common objects: Opportunities (by Stage), Cases (by Status), Leads (by Status). Users can drag cards between columns to update the picklist field value. It is a visual, board-style workflow management view."),
                        StudyTopic(id: "ab-s17-t18", number: 18, question: "What is the Path component in Lightning App Builder and what can be configured on it (stage values, key fields, guidance for success text)?", answer: "The Path component displays a visual progress bar of a record's stage/status values. Configuration options: which field drives the stages (typically Stage for Opportunities or Status for Cases), key fields to display for each stage (shows contextual fields when a stage is selected), and 'Guidance for Success' text for each stage (tips/checklists for advancing). It is added to a record page via App Builder."),
                        StudyTopic(id: "ab-s17-t19", number: 19, question: "What is the difference between Standard Navigation and Console Navigation in a Lightning App, and when is Console Navigation appropriate?", answer: "Standard Navigation: clicking a record opens it as a full-page view, replacing the previous page. Tabs are breadcrumb-based. Console Navigation: records open as tabs or sub-tabs within the same app window, allowing multiple records to be open simultaneously. Console Navigation is appropriate for service reps, call center agents, or any high-volume record users who need to work across many records without losing context."),
                        StudyTopic(id: "ab-s17-t20", number: 20, question: "How is a page layout assigned to a user — what is the role of the profile and the record type in determining which page layout is displayed?", answer: "Page layout assignment is a matrix of Profile + Record Type. In Setup > Object Manager > [Object] > Page Layout Assignment, each row represents a Profile, and each column represents a Record Type. The intersection cell specifies which layout users on that profile see when viewing records of that type. If only one record type exists, the profile directly determines the layout."),
                        StudyTopic(id: "ab-s17-t21", number: 21, question: "What elements can be placed on a page layout (fields, sections, related lists, buttons, custom links, actions, Visualforce pages) and which are controlled separately from the layout?", answer: "Page layout elements: fields, field sections, related lists, buttons (standard and custom), links, quick actions, Visualforce pages, Canvas apps, and the mobile/Lightning actions section. Controlled separately (not on the layout): field-level security (FLS), tab visibility, record type assignment, compact layouts, and Dynamic Forms field visibility (once migrated to Dynamic Forms). FLS is the most commonly confused separate control."),
                        StudyTopic(id: "ab-s17-t22", number: 22, question: "A company has two types of Contact records — individual consumers and business contacts — each requiring different visible fields and picklist values. What combination of features satisfies this?", answer: "Use Record Types (one for Consumer, one for Business Contact) to control different picklist values and page layouts. Assign each record type to the appropriate profiles. Configure separate page layouts for each record type showing only the relevant fields. Optionally, use Dynamic Forms with visibility filters for more granular field-level control within a single layout."),
                        StudyTopic(id: "ab-s17-t23", number: 23, question: "What configuration options are available when creating a new Lightning App (navigation items, utility bar components, supported form factors, user profile assignment)?", answer: "When creating a Lightning App in App Manager, you configure: (1) App name, description, and logo/color (branding), (2) Navigation items (which tabs/pages appear in the nav bar), (3) Utility Bar components (persistent bottom panel items like Phone, Notes, Recent Items), (4) Supported form factors (Desktop, Phone), (5) User profile assignment (which profiles can see this app). All options are set through the guided setup wizard."),
                        StudyTopic(id: "ab-s17-t24", number: 24, question: "What are Lightning App themes and how can an administrator customize the app's color and logo?", answer: "Lightning App themes control the visual branding of a Lightning app — specifically the header bar color (brand color) and the app logo image. These are configured in App Manager when creating or editing a Lightning App. The brand color applies to the app's navigation bar. Custom logos must be uploaded as images. Themes are per-app, not org-wide (org-wide theming uses My Domain login page settings)."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s4-obj2",
                    title: "Demonstrate the capabilities and use cases for custom buttons, links, and actions.",
                    topics: [
                        StudyTopic(id: "ab-s18-t1", number: 1, question: "What is a custom button in Salesforce and where can it be placed on a page layout?", answer: "A custom button is a clickable element that triggers a URL, Visualforce page, or (in Classic) JavaScript. It can be placed: in the button bar at the top of a detail page (Detail Page Button), in a related list (Related List Button), or in the list view (List Button). In Lightning Experience, custom buttons in the action bar are typically surfaced as actions rather than traditional buttons."),
                        StudyTopic(id: "ab-s18-t2", number: 2, question: "What content source types are available for a custom button (URL, Visualforce Page, JavaScript — noting JavaScript is Classic only)?", answer: "Content source options: (1) URL — navigates to a specified URL (can include field merge syntax for dynamic URLs), (2) Visualforce Page — opens a VF page, (3) JavaScript — executes JavaScript on the page (Classic only, not supported in Lightning Experience). In Lightning Experience, URL and VF page buttons are supported; JavaScript buttons are not rendered."),
                        StudyTopic(id: "ab-s18-t3", number: 3, question: "What is a custom link and how does it differ from a custom button in terms of display location?", answer: "A custom link appears inline within a page layout section (typically displayed as a hyperlink in the page body), while a custom button appears in the button bar area at the top of the record or in related lists. Both can navigate to URLs or VF pages, but their display placement and visual styling differ. Links blend into the field layout; buttons are standalone clickable elements."),
                        StudyTopic(id: "ab-s18-t4", number: 4, question: "What is an object-specific quick action and what objects does it belong to?", answer: "An object-specific quick action belongs to a specific standard or custom object and appears only on records of that object. It is created in Setup > Object Manager > [Object] > Buttons, Links, and Actions. Examples: a 'Schedule Meeting' action on the Contact object, or a 'Create Related Invoice' action on the Opportunity object. They have access to the context record's fields for pre-population."),
                        StudyTopic(id: "ab-s18-t5", number: 5, question: "What is a 'Log a Call' action and when would it be used?", answer: "A 'Log a Call' action is a pre-configured quick action that creates a Task record with Type = 'Call'. It is commonly placed on Contact, Lead, Opportunity, and Account objects for sales reps to quickly document call outcomes. The action layout typically includes Subject, Comments (call notes), and Status fields — minimizing required input for fast mobile logging."),
                        StudyTopic(id: "ab-s18-t6", number: 6, question: "How are quick actions surfaced on a Lightning record page vs. a Classic detail page?", answer: "Lightning record page: quick actions appear in the 'Salesforce Mobile and Lightning Experience Actions' section of the page layout and are displayed in the action bar (the row of buttons/icons) on the record. Dynamic Actions (in App Builder) can also be used. Classic detail page: actions appear in the 'Actions in the Publisher' section and are shown in the Chatter publisher bar. The rendering and placement mechanisms differ between platforms."),
                        StudyTopic(id: "ab-s18-t7", number: 7, question: "Can a quick action launch a Flow? If so, how?", answer: "Yes. Create a quick action of type 'Flow' and select a Screen Flow to launch. When the user clicks the action button, the Screen Flow opens as a modal overlay on the record page. The Flow can be pre-populated with record field values. This is the standard way to surface guided process wizards as clickable actions on a record without leaving the page."),
                        StudyTopic(id: "ab-s18-t8", number: 8, question: "A user needs to click a button on an Account record that opens a custom Visualforce page in a new window with the Account ID in the URL. Which feature satisfies this?", answer: "Create a custom button (Detail Page Button) with content source 'Visualforce Page' or 'URL'. Use the URL option with merge syntax: /apex/MyVFPage?id={!Account.Id}. Set the button behavior to 'Display in new window.' Add the button to the Account page layout. This passes the Account ID to the VF page and opens it in a separate browser window."),
                        StudyTopic(id: "ab-s18-t9", number: 9, question: "What are predefined field values in a quick action and how do they improve the user experience?", answer: "Predefined field values auto-populate specified fields on a quick action's form using values from the current record or static values. For example, a 'Create Related Contact' action on Account could pre-populate the Contact's AccountId and MailingCity from the Account. Users don't need to manually fill in known values, reducing errors and saving time — especially valuable in mobile contexts."),
                        StudyTopic(id: "ab-s18-t10", number: 10, question: "What is a global action and what makes it different from an object-specific action?", answer: "A global action is not associated with any specific object — it is accessible from anywhere in Salesforce (global header, mobile nav, any page). It does not have access to a contextual record's fields (unlike object-specific actions). Global actions are used for org-wide tasks like 'Create New Lead' or 'New Task' from anywhere. They are configured in Setup > Global Actions."),
                        StudyTopic(id: "ab-s18-t11", number: 11, question: "A company wants the 'Submit for Approval' action to appear on an Opportunity record page only when the Discount field exceeds 20%. Which feature and where must it be configured?", answer: "Use Dynamic Actions in Lightning App Builder. Open the Opportunity record page in App Builder, switch to Dynamic Actions mode for the actions section, find the 'Submit for Approval' action, and add a visibility filter: Discount__c > 20. The action will only render when the condition is met. This requires the page to use Dynamic Actions (not traditional page layout action assignment)."),
                        StudyTopic(id: "ab-s18-t12", number: 12, question: "What are Dynamic Actions in Lightning App Builder and how do they differ from placing actions on a page layout's action section?", answer: "Dynamic Actions moves action configuration from the page layout into Lightning App Builder, allowing visibility conditions (filters) on individual actions. Traditional page layout actions are static — either shown or not based on the profile/record type. Dynamic Actions allows conditional rendering: show 'Approve' action only when Status = 'Pending'; show 'Escalate' only for users with a specific permission. More granular and context-aware."),
                        StudyTopic(id: "ab-s18-t13", number: 13, question: "How do you configure a filter condition on a Dynamic Action so it only appears when a record's field meets a certain value?", answer: "In Lightning App Builder, with Dynamic Actions enabled on the record page, select an action and click 'Add Filter.' Define the filter: choose 'Record Field' as the filter type, select the field (e.g., Status__c), choose an operator (equals, not equals, greater than, etc.), and enter the value. The action only renders when the condition evaluates to true at page load. Multiple conditions can be ANDed together."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s4-obj3",
                    title: "Given a scenario, determine the declarative options available for incorporating Lightning components in an application.",
                    topics: [
                        StudyTopic(id: "ab-s19-t1", number: 1, question: "What standard Lightning components are available in Lightning App Builder for record pages?", answer: "Standard components available in App Builder for record pages include: Related Lists, Activity Timeline, Chatter Feed, Path, Highlights Panel, Report Chart, Recent Items, Rich Text (static text/HTML), Flow (embeds a Screen Flow), Record Detail (fields section), Tabs, Accordion, Custom components (LWC/Aura), and more. The component palette shows all available components when editing a page."),
                        StudyTopic(id: "ab-s19-t2", number: 2, question: "How is a standard or custom Lightning component added to a record page using Lightning App Builder?", answer: "Open the record's Lightning page in App Builder (from the record page via the gear icon > Edit Page, or directly in Setup). In the left panel, find the desired component in the component palette (standard or custom). Drag it onto the page canvas and drop it in the desired region/column. Configure its properties in the right panel. Save and Activate the page to publish it to users."),
                        StudyTopic(id: "ab-s19-t3", number: 3, question: "Can Lightning components be added to Experience Cloud (Community) pages declaratively?", answer: "Yes. Experience Builder (the Experience Cloud site editor) supports adding Lightning components to community pages declaratively — similar to App Builder for internal org pages. Standard and custom LWC/Aura components marked as available for Experience Cloud can be dragged onto community page templates. This enables rich, component-based external portals without code."),
                        StudyTopic(id: "ab-s19-t4", number: 4, question: "What is the Highlights Panel component in Lightning App Builder and what does it display?", answer: "The Highlights Panel is the component at the top of a Lightning record page that displays the compact layout fields — the most important identifying fields for the record (e.g., Account Name, Industry, Phone, Owner). It is powered by the object's compact layout configuration. It is typically the first component visible when a user opens a record and is always displayed prominently."),
                        StudyTopic(id: "ab-s19-t5", number: 5, question: "A business wants certain fields on a custom object record page to be hidden unless a picklist field equals 'Active'. What is the declarative solution?", answer: "Use Dynamic Forms in Lightning App Builder. Migrate the record page to Dynamic Forms, then add field components for the fields to be conditionally shown. Set a visibility filter on each field: 'Record Field: Status__c equals Active.' The fields will be hidden unless Status__c = 'Active.' No code, no multiple layouts needed."),
                        StudyTopic(id: "ab-s19-t6", number: 6, question: "What is a tab in a Lightning App and how are tabs associated with objects, Visualforce pages, or Lightning pages?", answer: "A tab in a Lightning App is a navigation item in the app's navigation bar. Tabs are associated with: custom object tabs (showing an object's list/detail views), Visualforce page tabs (hosting a VF page), Lightning component tabs (hosting a Lightning App Page or LWC), and web tabs (hosting a URL). Tabs are created in Setup > Tabs and then added to apps via App Manager."),
                        StudyTopic(id: "ab-s19-t7", number: 7, question: "What is a Dynamic Form component and how does it replace field sections on a record page?", answer: "The Dynamic Form component (enabled in App Builder) allows each field to be placed individually on the record page canvas — rather than having all fields in a block defined by the page layout. Each field becomes its own draggable component with its own visibility rules. This replaces the monolithic 'Record Detail' section from the page layout, enabling field-level conditional display without multiple layouts."),
                        StudyTopic(id: "ab-s19-t8", number: 8, question: "What is the utility bar in a Lightning App and what types of components can be placed in it?", answer: "The utility bar is a persistent panel anchored to the bottom of the screen in a Lightning App. Components that can be placed in it: Open CTI (phone), Notes, History, Macros, Omni-Channel (for service), Flow (a Screen Flow accessible anytime), Custom utility components (LWC/Aura). The utility bar is always visible and provides quick access to tools without navigating away from the current page."),
                        StudyTopic(id: "ab-s19-t9", number: 9, question: "What must be configured in an LWC's metadata configuration file (.js-meta.xml) to make it available as a draggable component in Lightning App Builder?", answer: "In the .js-meta.xml file, the component must be exposed with: <isExposed>true</isExposed>, and the <targets> must include <target>lightning__RecordPage</target> (or AppPage, HomePage, etc.) for the relevant page types. Additionally, <targetConfigs> can define design properties that appear as configurable options in App Builder's property panel. Without isExposed=true, the component won't appear in App Builder."),
                        StudyTopic(id: "ab-s19-t10", number: 10, question: "What standard Lightning components can be added to a record page in App Builder to display related or contextual information (Related Lists, Activity Timeline, Chatter Feed, Path, Recently Viewed Items)?", answer: "Standard components for related/contextual info: Related Lists (shows child records in a list), Activity Timeline (shows tasks, events, emails, logs chronologically), Chatter Feed (shows the record's collaboration feed), Path (shows stage progression), Recently Viewed Items (shows records the user recently accessed), Report Chart (embeds a report's chart), and Record Detail (shows the layout's fields). All available in the App Builder palette."),
                        StudyTopic(id: "ab-s19-t11", number: 11, question: "What is the Flow component in Lightning App Builder and how is it used to embed a Screen Flow directly on a record page?", answer: "The Flow component is a standard Lightning App Builder component that embeds a Screen Flow directly in the record page layout. In App Builder, drag the Flow component onto the page, then in its properties panel, select which Screen Flow to display. The Flow renders inline on the page. Input variables in the Flow can be pre-populated with record field values using the component's property bindings, allowing context-aware embedded flows."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s4-obj4",
                    title: "Describe the programmatic customizations available for incorporating custom Lightning components in an application.",
                    topics: [
                        StudyTopic(id: "ab-s20-t1", number: 1, question: "What is a Lightning Web Component (LWC)?", answer: "A Lightning Web Component (LWC) is a modern JavaScript-based UI component framework built on Web Standards (Custom Elements, Shadow DOM, ES6+ modules). LWCs are the current Salesforce standard for custom UI development. They are faster, lighter, and more aligned with browser standards than their predecessor (Aura components). They can be deployed to Lightning pages, Experience Cloud, and email templates."),
                        StudyTopic(id: "ab-s20-t2", number: 2, question: "What is the difference between an Aura component and a Lightning Web Component (LWC)?", answer: "Aura (also called 'Classic Lightning Components') uses a proprietary Salesforce framework with its own lifecycle hooks, event system, and XML/JavaScript hybrid syntax. LWC uses W3C Web Standards — HTML templates, ES6 JavaScript, and standard browser APIs. LWC is more performant, has smaller learning curve for web developers, and is the recommended choice for new development. Aura components can coexist with LWC on the same page."),
                        StudyTopic(id: "ab-s20-t3", number: 3, question: "How is a custom LWC exposed in Lightning App Builder so it can be dragged onto a page?", answer: "The LWC's .js-meta.xml configuration file must: (1) set <isExposed>true</isExposed>, and (2) include relevant <targets> (e.g., <target>lightning__RecordPage</target>). Optional <targetConfigs> define admin-configurable properties that appear in the App Builder property panel. After deployment, the component appears in the App Builder component palette under 'Custom Components' and can be dragged onto the canvas."),
                        StudyTopic(id: "ab-s20-t4", number: 4, question: "When is a custom LWC required rather than a standard Lightning component for a UI requirement?", answer: "A custom LWC is required when: no standard component provides the needed functionality (e.g., a custom interactive chart, a specialized data entry form, a third-party JavaScript library integration), the UI needs real-time data manipulation not possible with standard components, the business requires a branded custom widget, or the component needs to emit and respond to custom events across a complex page structure."),
                        StudyTopic(id: "ab-s20-t5", number: 5, question: "What is a Visualforce page and when would it still be required in a Lightning Experience context?", answer: "A Visualforce page is an HTML-like markup page that uses Apex controllers for server-side logic. In Lightning Experience, VF pages are rendered in an iframe. They are still required when: migrating legacy Classic applications that haven't been rewritten, custom buttons link to VF pages, specific PDF rendering (using renderAs='pdf' on the <apex:page> tag) is needed, or integrations use VF-specific endpoints. New development should use LWC/Aura instead."),
                    ]
                )
            ]
        ),

        // Section 5: App Deployment (34 topics)
        StudySection(
            id: "ab-s5",
            title: "App Deployment",
            color: Color(red: 0.80, green: 0.35, blue: 0.10),
            lightColor: Color(red: 1.00, green: 0.93, blue: 0.90),
            icon: "shippingbox.fill",
            objectives: [
                StudyObjective(
                    id: "ab-s5-obj1",
                    title: "Given a set of business requirements, recommend a solution for key milestones and considerations when managing the application lifecycle and various types of sandboxes.",
                    topics: [
                        StudyTopic(id: "ab-s21-t1", number: 1, question: "What are the four types of Salesforce sandboxes?", answer: "Four sandbox types: (1) Developer — small storage, copies metadata only, 1-day refresh. (2) Developer Pro — more storage than Developer, copies metadata only, 1-day refresh. (3) Partial Copy — copies metadata + a sample of data (via sandbox template), 5-day refresh. (4) Full — exact copy of production including all data and metadata, 29-day refresh. Higher tiers cost more and take longer to provision."),
                        StudyTopic(id: "ab-s21-t2", number: 2, question: "Does a Developer sandbox copy production data records?", answer: "No. A Developer sandbox copies only metadata (configurations, code, custom objects, page layouts, etc.) — not production data records. This makes it fast to provision and appropriate for development and unit testing. If you need data for testing, you must manually create test records or use a data generation tool. Only Partial Copy and Full sandboxes include production data."),
                        StudyTopic(id: "ab-s21-t3", number: 3, question: "What is the data storage limit for a Developer sandbox?", answer: "A Developer sandbox has 200 MB of data storage and 200 MB of file storage. This is sufficient for development and unit testing but not for performance testing or UAT with realistic data volumes. The small storage cap is intentional — it keeps developers from relying on large datasets in their isolated environments."),
                        StudyTopic(id: "ab-s21-t4", number: 4, question: "What is the data storage limit for a Developer Pro sandbox?", answer: "A Developer Pro sandbox has 1 GB of data storage and 1 GB of file storage. This is larger than a standard Developer sandbox, making it better suited for integration testing, more complex development scenarios, or teams that need slightly more data for testing without committing to a Partial Copy sandbox."),
                        StudyTopic(id: "ab-s21-t5", number: 5, question: "What is the data storage limit for a Partial Copy sandbox?", answer: "A Partial Copy sandbox has 5 GB of data storage. It includes a sample of production data (filtered by a sandbox template). The 5 GB limit is designed for UAT and QA testing with representative data without requiring a full production dataset. Templates define which objects and records are copied."),
                        StudyTopic(id: "ab-s21-t6", number: 6, question: "What is the data storage limit for a Full sandbox?", answer: "A Full sandbox matches production's data storage allocation — it has the same storage capacity as the production org. It contains a complete copy of all production data and metadata. This makes it suitable for performance testing, load testing, and final UAT with real data volumes. Full sandboxes are the most expensive type."),
                        StudyTopic(id: "ab-s21-t7", number: 7, question: "What is the refresh interval for a Developer and Developer Pro sandbox?", answer: "Both Developer and Developer Pro sandboxes can be refreshed once every 1 day (24 hours). This frequent refresh capability allows developers to quickly reset their environment if needed or create a fresh copy from production. After a refresh, the sandbox URL and ID change, so connected tools may need reconfiguration."),
                        StudyTopic(id: "ab-s21-t8", number: 8, question: "What is the refresh interval for a Partial Copy sandbox?", answer: "A Partial Copy sandbox can be refreshed once every 5 days. The 5-day interval reflects the time needed to copy the data sample from production. After refresh, existing sandbox configuration is replaced, so any sandbox-specific settings or post-refresh customizations must be re-applied."),
                        StudyTopic(id: "ab-s21-t9", number: 9, question: "What is the refresh interval for a Full sandbox?", answer: "A Full sandbox can be refreshed once every 29 days. The long interval is due to the time required to copy all production data. Full sandbox refreshes are major operations typically planned around sprint cycles or release events. Between refreshes, production changes must be manually deployed into the sandbox."),
                        StudyTopic(id: "ab-s21-t10", number: 10, question: "What is a sandbox template and with which sandbox type is it used?", answer: "A sandbox template is a configuration that defines which objects and records are copied when creating or refreshing a Partial Copy sandbox. You specify which standard and custom objects to include. Salesforce will copy a sample of records (up to the 5 GB limit) from those objects. Templates are used only with Partial Copy sandboxes — Developer sandboxes copy no data, Full sandboxes copy all data."),
                        StudyTopic(id: "ab-s21-t11", number: 11, question: "A company needs to perform UAT with a representative subset of production data. Which sandbox type is appropriate?", answer: "Partial Copy sandbox. It provides up to 5 GB of production data (selected via a sandbox template) and all production metadata. This gives UAT testers realistic data to validate business processes without needing the full production dataset. Developer sandboxes lack data; Full sandboxes are more expensive and have 29-day refresh intervals."),
                        StudyTopic(id: "ab-s21-t12", number: 12, question: "A company needs to run performance and load tests that mimic production-scale data. Which sandbox type is required?", answer: "Full sandbox. Only a Full sandbox contains a complete copy of all production data at production scale. Performance and load testing requires production-volume data to accurately simulate governor limit behavior, query performance, and automation throughput. Partial Copy's 5 GB limit is insufficient for true production-scale load testing."),
                        StudyTopic(id: "ab-s21-t13", number: 13, question: "What is the recommended application lifecycle management (ALM) deployment path from development through production?", answer: "Standard ALM path: (1) Development in Developer sandboxes (individual developers), (2) Integration sandbox (merge and integration test), (3) QA/Staging sandbox (quality assurance testing), (4) UAT sandbox (Partial Copy or Full for user acceptance testing), (5) Production deployment. Change sets or DevOps tools (DevOps Center, Copado, Gearset) move metadata between environments."),
                        StudyTopic(id: "ab-s21-t14", number: 14, question: "What is DevOps Center in Salesforce and how does it compare to change sets as a deployment mechanism?", answer: "DevOps Center is Salesforce's native Git-based DevOps tool that provides version control integration, work item tracking, and pipeline-based deployments. It is more robust than change sets: it tracks all changes in Git, supports branching strategies, provides deployment history, and enables team collaboration. Change sets are manual, point-in-time, and lack version control. DevOps Center is Salesforce's recommended modern replacement for change-set-based deployments."),
                        StudyTopic(id: "ab-s21-t15", number: 15, question: "What is a scratch org in the Salesforce DX development model and how does it differ from a sandbox in terms of purpose and lifespan?", answer: "A scratch org is a short-lived (up to 30 days), source-driven, fully configurable Salesforce environment created from a project configuration file. It is designed for development and testing in the Salesforce DX model where source code is the source of truth. Unlike sandboxes (which are copies of production), scratch orgs are created from scratch with only the features you need. They are disposable and version-controlled."),
                        StudyTopic(id: "ab-s21-t16", number: 16, question: "When multiple developers are working in separate Developer sandboxes on overlapping customizations, what process risk must be managed before merging to a shared integration sandbox?", answer: "The risk is metadata conflicts — two developers may have modified the same metadata component (e.g., the same page layout, Flow, or Apex class) in incompatible ways. Before merging, teams must: compare changes, resolve conflicts (manually reconciling differences), and sequence deployments carefully. This is why version control (Git) is strongly recommended — it enables diff/merge tooling to manage overlapping changes systematically."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s5-obj2",
                    title: "Given a use case, demonstrate knowledge, viability, and troubleshooting when using change sets.",
                    topics: [
                        StudyTopic(id: "ab-s22-t1", number: 1, question: "What is a change set and what types of metadata components can be included in one?", answer: "A change set is a deployment container that packages metadata components (not data) for migration between connected Salesforce orgs (typically sandbox to production). Components that can be included: Apex classes/triggers, Visualforce pages/components, custom objects/fields, page layouts, profiles (partial), permission sets, Flows, reports, dashboards, email templates, and many other metadata types. Data records cannot be deployed via change sets."),
                        StudyTopic(id: "ab-s22-t2", number: 2, question: "What is an outbound change set vs. an inbound change set?", answer: "Outbound change set: created in the source org (e.g., sandbox), where you add components and upload the set to the connected target org. Inbound change set: received in the target org (e.g., production) from a connected source org — it appears in the 'Inbound Change Sets' section where it can be validated and deployed. The same change set is outbound from the sender's perspective and inbound from the receiver's perspective."),
                        StudyTopic(id: "ab-s22-t3", number: 3, question: "What is a deployment connection and what must be configured between two orgs before change sets can be sent?", answer: "A deployment connection establishes a trusted pathway between two Salesforce orgs for change set transfers. To send change sets from Sandbox A to Production, a connection must be authorized in both orgs (typically configured under Setup > Deploy > Deployment Settings). Without an authorized connection, the upload button in the outbound change set is not available."),
                        StudyTopic(id: "ab-s22-t4", number: 4, question: "What is the difference between 'Validate' and 'Deploy' when processing an inbound change set?", answer: "Validate: runs all component checks and Apex tests against the target org without actually saving any changes. It confirms that the change set would succeed if deployed — useful for pre-deployment verification. Deploy: applies the changes permanently to the target org. A validated deployment can be Quick Deployed within 10 days if no changes occur, skipping the test phase for faster deployment."),
                        StudyTopic(id: "ab-s22-t5", number: 5, question: "What Apex test coverage requirement must be met before deploying to a production org via change set?", answer: "Production deployments require: overall org Apex code coverage of at least 75%, AND every Apex trigger must have at least 1% test coverage. Change sets including Apex classes/triggers will run all local Apex tests. If coverage drops below 75% after including the new code, the deployment fails. Always check current org coverage before deploying."),
                        StudyTopic(id: "ab-s22-t6", number: 6, question: "What happens if a component in a change set has a dependency on another component that is not included in the change set?", answer: "The deployment fails with an error identifying the missing dependent component. Change sets do not automatically include dependencies — the admin must manually add all required components. Best practice: use the 'Add Dependencies' button when adding components to a change set to identify and include all required related components."),
                        StudyTopic(id: "ab-s22-t7", number: 7, question: "Can change sets be used to delete metadata components from a target org?", answer: "No. Change sets cannot delete components — they can only add or update. To delete metadata from a target org, you must manually delete it in that org, or use the Metadata API with a destructiveChanges.xml file via Workbench, SFDX CLI, or a third-party DevOps tool. This is one of the key limitations of change sets as a deployment mechanism."),
                        StudyTopic(id: "ab-s22-t8", number: 8, question: "What is a Quick Deploy and when is it available after a successful change set validation?", answer: "Quick Deploy allows you to deploy a previously validated change set without re-running Apex tests, provided: (1) the change set was validated within the last 10 days, (2) all tests passed during validation, and (3) no changes have been made to the org since validation. This speeds up production deployments by skipping the (sometimes slow) test execution phase."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s5-obj3",
                    title: "Describe the use cases and considerations when using unmanaged and managed packages.",
                    topics: [
                        StudyTopic(id: "ab-s23-t1", number: 1, question: "What is an unmanaged package and what are its primary use cases?", answer: "An unmanaged package is a collection of metadata components that can be installed into any Salesforce org. After installation, all components are fully editable — there is no code protection. Primary use cases: sharing open-source Salesforce solutions, distributing starter templates or developer tools, internal org-to-org metadata transfer, and community-shared resources on the AppExchange (typically free, open components). No upgrade path exists — each install is standalone."),
                        StudyTopic(id: "ab-s23-t2", number: 2, question: "What is a managed package and what protections does it provide to the package developer?", answer: "A managed package is a locked distribution of metadata from a registered Salesforce Partner ISV org. Apex code is obfuscated (not readable by installers), core components are protected from modification, and the ISV can push upgrades to installed orgs. A namespace prefix prevents component name conflicts with the installing org. Managed packages are required for publicly listed AppExchange products that undergo Security Review."),
                        StudyTopic(id: "ab-s23-t3", number: 3, question: "What is a namespace prefix in a managed package and why does it matter?", answer: "A namespace prefix is a unique string registered to the ISV's org that is prepended to all API names of package components (e.g., myapp__CustomObject__c, myapp__MyFlow). This prevents naming conflicts between package components and the installing org's custom components. Namespace prefixes must be globally unique across all Salesforce orgs and cannot be changed after registration."),
                        StudyTopic(id: "ab-s23-t4", number: 4, question: "Can a managed package be uninstalled from a Salesforce org and what are the considerations?", answer: "Yes, a managed package can be uninstalled, but with significant considerations: all components (objects, fields, Apex code, layouts) installed by the package are removed, along with all data stored in the package's custom objects. Uninstalling is irreversible for the data. If the org has custom code or automation referencing package components, those references will break after uninstall. Always test uninstall in a sandbox first."),
                        StudyTopic(id: "ab-s23-t5", number: 5, question: "What is Salesforce Package 2 (2GP) and how does it differ from first-generation packages (1GP)?", answer: "Second-generation packages (2GP) use the Salesforce DX development model — they are source-driven, version-controlled, and support unlocked packages (editable by the installer) and managed packages (protected). 2GP packages are created using SFDX CLI. First-generation packages (1GP) are created through the classic package setup UI and are less integrated with version control. 2GP is Salesforce's modern packaging model."),
                    ]
                ),
                StudyObjective(
                    id: "ab-s5-obj4",
                    title: "Given a scenario, determine the appropriate deployment plan.",
                    topics: [
                        StudyTopic(id: "ab-s24-t1", number: 1, question: "When deploying a set of changes that includes new custom fields, a new Flow, and updated page layouts, what is the correct deployment sequence to minimize errors?", answer: "Deploy in dependency order: (1) Custom fields first (the Flow and layouts depend on them), (2) Flow (depends on the new fields), (3) Page layouts (depend on the new fields and potentially reference the Flow as an action). Deploying in wrong order causes errors because dependent components reference components that don't yet exist in the target org."),
                        StudyTopic(id: "ab-s24-t2", number: 2, question: "What deployment tool should a team use when deploying to production with a requirement for version control, rollback capability, and automated testing?", answer: "A Git-integrated DevOps tool such as Salesforce DevOps Center, Copado, Gearset, or Flosum. These tools connect to a Git repository for version control, maintain deployment history (enabling rollback), integrate with CI/CD pipelines for automated testing before deployment, and provide audit trails. Change sets lack all these capabilities. Salesforce CLI + source-format deployments are also viable for advanced teams."),
                        StudyTopic(id: "ab-s24-t3", number: 3, question: "A deployment to production failed due to a code coverage error. What steps should the team take to troubleshoot and resolve it?", answer: "Steps: (1) Review the deployment error log to identify which classes or triggers have insufficient coverage. (2) In the sandbox, run all Apex tests and review coverage report — identify untested code paths. (3) Write additional test methods to cover the failing code. (4) Re-run tests to confirm coverage exceeds 75% org-wide and all triggers have >1% coverage. (5) Redeploy via change set or CLI after confirming coverage."),
                        StudyTopic(id: "ab-s24-t4", number: 4, question: "What is the difference between a delta deployment and a full deployment, and when would you use each?", answer: "Delta deployment: deploys only the components that have changed since the last deployment — faster, lower risk, smaller footprint. Full deployment: deploys all metadata components in the project, regardless of changes — ensures the target org exactly matches the source. Use delta for routine incremental releases. Use full for initial org builds, after a full refresh, or when you suspect the target org has drifted from the source."),
                        StudyTopic(id: "ab-s24-t5", number: 5, question: "What is a destructiveChanges.xml file and when must it be used in a Salesforce deployment?", answer: "A destructiveChanges.xml file is a metadata API artifact that specifies components to be deleted in the target org during a deployment. It must be used when you want to remove custom fields, objects, classes, Flows, or other metadata components via CLI or API deployment — since change sets cannot delete components. Include it alongside the package.xml in the deployment package to perform deletions."),
                    ]
                )
            ]
        )

    ]
}
